-- Semilla: 246 ejercicios del catálogo (dataset traducido)
INSERT INTO public.exercises (id, name, muscle_group, primary_muscle, equipment, gif_url, instructions) VALUES
  ('3303', 'Bandera humana (Flag)', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/3303-pQ0Mx1Z.webm', 'Comienza sujetando un poste vertical con ambas manos, palmas una frente a la otra, y los brazos completamente extendidos.
Activa el core y levanta las piernas del suelo, manteniéndolas rectas.
Usando la fuerza del core y de la parte superior del cuerpo, levanta las piernas hasta que queden paralelas al suelo.
Mantén esta posición todo el tiempo que puedas, conservando una línea corporal recta.
Baja lentamente las piernas de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0260', 'Capullos (Cocoons)', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/0260-SLKj2pX.webm', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.
Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.
Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.
Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3016', 'Curl-up', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/3016-g2oKspu.webm', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.
Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.
Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.
Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0641', 'Otis up', 'Abdomen', 'Abdominales', 'Con Lastre', '/assets/exercises/0641-UVL20oz.webm', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.
Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.
Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.
Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0003', 'Bicicleta abdominal', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/0003-1ZFqTDN.webm', 'Túmbate sobre tu espalda con las manos colocadas detrás de la cabeza.
Levanta las piernas del suelo y flexiona las rodillas formando un ángulo de 90 grados.
Lleva el codo derecho hacia la rodilla izquierda mientras simultáneamente estiras la pierna derecha.
Regresa a la posición inicial y repite el movimiento del lado opuesto, llevando el codo izquierdo hacia la rodilla derecha mientras estiras la pierna izquierda.
Continúa alternando lados con un movimiento de pedaleo durante el número de repeticiones deseado.'),
  ('0870', 'Butt-ups', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/0870-qcNN2FN.webm', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.
Coloca las manos a los lados, con las palmas hacia abajo.
Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho.
En la parte más alta del movimiento, contrae el abdomen y haz una pausa breve.
Baja lentamente las piernas de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0276', 'Dead bug', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/0276-iny3m5y.webm', 'Túmbate boca arriba con los brazos extendidos hacia el techo.
Flexiona las rodillas y levanta las piernas del suelo, formando un ángulo de 90 grados en las caderas y las rodillas.
Activa el core y la zona lumbar para presionar la zona lumbar contra el suelo.
Baja lentamente el brazo derecho y la pierna izquierda hacia el suelo, manteniéndolos rectos y justo por encima del suelo.
Haz una pausa breve y luego vuelve a la posición inicial.
Repite el movimiento con el brazo izquierdo y la pierna derecha.
Continúa alternando lados durante el número de repeticiones deseado.'),
  ('1471', 'Gusano (Inchworm)', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/1471-ZgsNQ6d.webm', 'Comienza de pie con los pies separados a la altura de las caderas.
Inclínate hacia adelante desde la cintura y coloca las manos en el suelo frente a ti.
Camina con las manos hacia adelante hasta quedar en posición de plancha alta, con el cuerpo en línea recta de la cabeza a los pies.
Haz una pausa breve, luego camina con las manos de vuelta hacia los pies, manteniendo las piernas lo más rectas posible.
Cuando las manos lleguen a los pies, ponte de pie de nuevo en la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1014', 'V-up con banda', 'Abdomen', 'Abdominales', 'Bandas Elásticas', '/assets/exercises/1014-H6ETwO9.webm', 'Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.
Activando el abdomen, levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies.
Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0001', '3/4 sit-up', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/0001-2gPfomN.webm', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.
Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.
Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.
Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0138', 'Bottoms-up', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/0138-CI6baTY.webm', 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.
Flexiona las rodillas y llévalas hacia el pecho, manteniendo los pies fuera del suelo.
Activando el abdomen, levanta las caderas del suelo, llevando las rodillas hacia la cabeza.
Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0243', 'Twist en polea', 'Abdomen', 'Abdominales', 'Polea', '/assets/exercises/0243-aVs3BR3.webm', 'Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable.
Sujeta el mango del cable con ambas manos frente al pecho, manteniendo los brazos ligeramente flexionados.
Activa el core y gira el torso hacia la derecha, tirando del cable a través de tu cuerpo.
Haz una pausa breve al final del movimiento, sintiendo la contracción en el abdomen y los oblicuos.
Regresa lentamente a la posición inicial, resistiendo la tracción del cable.
Repite el movimiento hacia el lado izquierdo.
Continúa alternando lados durante el número de repeticiones deseado.'),
  ('2429', 'Frog crunch', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/2429-FFRP97T.webm', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.
Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.
Activando el abdomen, levanta la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso forme un ángulo de 45 grados.
Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3296', 'Front lever', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/3296-PkCN2lv.webm', 'Comienza colgado de una barra de dominadas con agarre prono, manos separadas a la altura de los hombros.
Activa el core y lleva los omóplatos hacia abajo y atrás.
Flexiona las rodillas y llévalas hacia el pecho.
Al mismo tiempo, levanta las piernas y extiéndelas rectas frente a ti, manteniendo el cuerpo paralelo al suelo.
Mantén esta posición todo el tiempo que puedas, intentando lograr una posición completa de palanca frontal.
Para soltar, baja lentamente las piernas y regresa a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3147', 'Retroversión pélvica', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/3147-NKJ8o6x.webm', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.
Coloca las manos a los lados del cuerpo.
Activa el abdomen e inclina la pelvis hacia arriba, presionando la zona lumbar contra el suelo.
Mantén esta posición durante unos segundos, concentrándote en contraer el abdomen.
Deshaz la inclinación y vuelve a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3119', 'Sentadilla profunda', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/3119-75Bgtjy.webm', 'Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.
Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás como si te sentaras en una silla.
Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento.
Baja hasta que los muslos queden paralelos al suelo o hasta donde puedas llegar cómodamente.
Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0735', 'Sit-up v. 2', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/0735-Bn6TXyO.webm', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.
Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.
Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.
Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('2329', 'Spine twist', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/2329-2jl9K55.webm', 'Siéntate en el suelo con las piernas extendidas frente a ti.
Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera.
Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.
Activa el abdomen y gira lentamente el torso hacia la derecha, llevando el codo derecho hacia la rodilla izquierda.
Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.
Repite el giro hacia el lado izquierdo, llevando el codo izquierdo hacia la rodilla derecha.
Continúa alternando lados durante el número de repeticiones deseado.'),
  ('0871', 'Tuck crunch', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/0871-BMMolZ3.webm', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.
Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.
Activando el abdomen, levanta los omóplatos del suelo y lleva las rodillas hacia el pecho, curvando al mismo tiempo la parte superior del cuerpo hacia las rodillas.
Haz una pausa de un momento en la parte superior, luego baja lentamente los omóplatos y extiende las piernas de nuevo a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0274', 'Crunch floor', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/0274-TFqbd8t.webm', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.
Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.
Activa el abdomen y levanta los hombros del suelo, flexionándote hacia adelante en dirección a las rodillas.
Haz una pausa breve en la parte alta, luego baja lentamente los hombros de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3301', 'Frog planche', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/3301-rQhGcin.webm', 'Comienza en posición de flexión de brazos con las manos separadas a la altura de los hombros y los pies juntos.
Dobla los codos y baja el cuerpo hacia el suelo, manteniendo la espalda recta.
Mientras bajas el cuerpo, levanta los pies del suelo y lleva las rodillas hacia el pecho.
Mantén esta posición durante unos segundos, luego extiende las piernas de nuevo y empújate hacia arriba a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3315', 'Maltesa completa (Maltese)', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/3315-YRaCa5Y.webm', 'Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos rectos hacia los lados.
Inclínate lentamente hacia adelante, manteniendo los brazos rectos, hasta que la parte superior del cuerpo quede paralela al suelo.
Activa el core y mantén esta posición durante unos segundos.
Regresa a la posición inicial empujando con los pies y volviendo a ponerte de pie.
Repite el número de repeticiones deseado.'),
  ('3299', 'Plancha completa', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/3299-YZ4961r.webm', 'Comienza en posición de flexión de brazos con las manos separadas a la altura de los hombros y los dedos apuntando hacia adelante.
Activa el core y desplaza lentamente el peso hacia adelante, levantando los pies del suelo.
Continúa desplazando el peso hacia adelante hasta que el cuerpo quede paralelo al suelo, equilibrándote sobre las manos.
Mantén esta posición todo el tiempo que puedas, conservando una línea corporal recta.
Baja lentamente los pies de nuevo al suelo y regresa a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0467', 'Dominadas gorila', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/0467-bmwlYvD.webm', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.
Sujeta una barra de dominadas con agarre prono, ligeramente más ancho que la altura de los hombros.
Cuélgate de la barra con los brazos completamente extendidos y las palmas hacia afuera.
Activa el core y tira del cuerpo hacia la barra, llevando la barbilla por encima de la barra.
Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0469', 'Groin crunch', 'Abdomen', 'Abdominales', 'Peso Corporal', '/assets/exercises/0469-mWppALS.webm', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.
Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.
Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho.
Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3533', 'Cuádriceps', 'Piernas', 'Cuádriceps', 'Peso Corporal', '/assets/exercises/3533-6YUfHPL.webm', 'Ponte de pie con los pies separados a la altura de los hombros.
Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás como si te sentaras en una silla.
Mantén el pecho arriba y la espalda recta.
Baja hasta que los muslos queden paralelos al suelo.
Empuja con los talones para volver a ponerte de pie en la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0786', 'Sentadilla jerk', 'Piernas', 'Cuádriceps', 'Barra', '/assets/exercises/0786-IMRsOCn.webm', 'Comienza con la barra apoyada sobre los hombros y los pies separados a la altura de los hombros.
Baja el cuerpo a una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con la punta de los pies.
Al llegar al punto más bajo de la sentadilla, empuja con fuerza a través de las piernas y eleva la barra por encima de la cabeza.
Cuando la barra alcance su punto más alto, baja rápidamente a una posición de zancada dividida, con un pie adelante y otro atrás.
Recibe la barra por encima de la cabeza con los brazos completamente extendidos y la rodilla trasera tocando ligeramente el suelo.
Ponte de pie desde la posición dividida, juntando de nuevo los pies.
Baja la barra de nuevo a los hombros y repite el número de repeticiones deseado.'),
  ('1489', 'Sentadilla Sissy', 'Piernas', 'Cuádriceps', 'Peso Corporal', '/assets/exercises/1489-xdYPUtE.webm', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.
Sujétate de un objeto estable para mantener el equilibrio si es necesario.
Baja lentamente el cuerpo doblando las rodillas e inclinándote hacia atrás, manteniendo el torso erguido.
Continúa bajando hasta que los muslos queden paralelos al suelo o tan lejos como puedas llegar cómodamente.
Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0776', 'Snatch pull', 'Piernas', 'Cuádriceps', 'Barra', '/assets/exercises/0776-dG5Smob.webm', 'Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti.
Flexiona las rodillas y dobla las caderas para bajar a una posición de sentadilla, agarrando la barra con un agarre prono.
Mantén la espalda recta y el pecho elevado mientras empujas con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas.
Cuando la barra llegue a la altura de la cadera, tira de ella hacia arriba de forma explosiva, encogiendo los hombros y llevando los codos altos y hacia los lados.
Cuando la barra alcance su punto más alto, baja rápidamente debajo de ella, llevando tu cuerpo a una posición de sentadilla profunda.
Recibe la barra por encima de la cabeza con los brazos completamente extendidos y las rodillas flexionadas.
Ponte de pie extendiendo las caderas y las rodillas, manteniendo la barra por encima de la cabeza.
Baja la barra de nuevo a la posición inicial invirtiendo el movimiento.
Repite el número de repeticiones deseado.'),
  ('2133', 'Paseo del granjero', 'Piernas', 'Cuádriceps', 'Mancuernas', '/assets/exercises/2133-qPEzJjA.webm', 'Ponte de pie con una mancuerna en cada mano, palmas hacia los costados.
Mantén la espalda recta y los hombros hacia atrás.
Da pasos pequeños y controlados hacia adelante, manteniendo una postura erguida.
Continúa caminando durante la distancia o el tiempo deseado.
Para terminar, deja de caminar y baja con cuidado las mancuernas a los costados.'),
  ('1472', 'Forward jump', 'Piernas', 'Cuádriceps', 'Peso Corporal', '/assets/exercises/1472-uZKq7lo.webm', 'Ponte de pie con los pies separados a la altura de los hombros.
Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.
Balancea los brazos hacia atrás para generar impulso.
Salta hacia adelante de forma explosiva, extendiendo las caderas, las rodillas y los tobillos.
Aterriza suavemente sobre la punta de los pies y pasa de inmediato al siguiente salto.
Repite el número de repeticiones deseado.'),
  ('2368', 'Sentadilla búlgara (split)s', 'Piernas', 'Cuádriceps', 'Peso Corporal', '/assets/exercises/2368-9E25EOx.webm', 'Ponte de pie con los pies separados a la altura de los hombros.
Da un paso adelante con un pie y colócalo aproximadamente a dos pies de distancia por delante del otro pie.
Baja el cuerpo flexionando las rodillas y las caderas, manteniendo la espalda recta.
Sigue bajando hasta que el muslo delantero quede paralelo al suelo y la rodilla trasera quede justo por encima del suelo.
Haz una pausa breve, luego empuja con el talón delantero para volver a la posición inicial.
Repite el número de repeticiones deseado y luego cambia de pierna y repite.'),
  ('1473', 'Backward jump', 'Piernas', 'Cuádriceps', 'Peso Corporal', '/assets/exercises/1473-SaDOwk7.webm', 'Ponte de pie con los pies separados a la altura de los hombros.
Flexiona ligeramente las rodillas y salta hacia atrás, impulsándote con ambos pies.
Aterriza suavemente sobre la punta de los pies, flexionando las rodillas para absorber el impacto.
Repite el número de repeticiones deseado.'),
  ('0020', 'Balance board', 'Piernas', 'Cuádriceps', 'Peso Corporal', '/assets/exercises/0020-xAySMB0.webm', 'Coloca la tabla de equilibrio sobre una superficie plana.
Sube a la tabla de equilibrio con un pie, asegurándote de que esté centrado.
Desplaza lentamente tu peso hacia el pie que está sobre la tabla de equilibrio, manteniendo el core activado.
Mantén el equilibrio y la estabilidad mientras sostienes la posición durante el tiempo deseado.
Repite el ejercicio con el otro pie.'),
  ('3552', 'Quick feet v. 2', 'Piernas', 'Cuádriceps', 'Peso Corporal', '/assets/exercises/3552-mweqJin.webm', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados.
Comienza moviendo los pies rápidamente hacia arriba y hacia abajo, como si estuvieras corriendo en el sitio.
Mantén los movimientos rápidos y ligeros, concentrándote en quedarte sobre la punta de los pies.
Continúa durante el tiempo o el número de repeticiones deseado.'),
  ('0750', 'Sentadilla en silla en multipower (Smith)', 'Piernas', 'Cuádriceps', 'Multipower (Smith)', '/assets/exercises/0750-Gu2rNJd.webm', 'Ajusta la altura de la barra de la máquina Smith a una posición cómoda.
Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.
Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios.
Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo doblando las rodillas y las caderas.
Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.
Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0124', 'Sentadilla con agarre ancho con barra', 'Piernas', 'Cuádriceps', 'Barra', '/assets/exercises/0124-s7HX1BY.webm', 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.
Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.
Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.
Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.
Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0026', 'Sentadilla en banco con barra', 'Piernas', 'Cuádriceps', 'Barra', '/assets/exercises/0026-W9pFVv1.webm', 'Coloca una barra en un soporte de sentadillas a la altura del pecho.
Ponte de pie de espaldas al soporte, con los pies separados a la altura de los hombros.
Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.
Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.
Levanta la barra del soporte y retrocede un paso, asegurándote de que los pies sigan separados a la altura de los hombros.
Baja el cuerpo hacia una sentadilla, manteniendo las rodillas alineadas con los dedos de los pies.
Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0585', 'Extensión de piernas en máquina', 'Piernas', 'Cuádriceps', 'Máquina de Palanca', '/assets/exercises/0585-my33uHU.webm', 'Ajusta la altura del asiento y el respaldo de la máquina a tu cuerpo.
Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre la almohadilla para los pies.
Sujeta las asas o las barras laterales para mayor estabilidad.
Extiende las piernas hacia adelante enderezando las rodillas, levantando el peso.
Haz una pausa breve en lo alto, luego baja lentamente el peso de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0851', 'Sentadilla Sissy con lastre', 'Piernas', 'Cuádriceps', 'Con Lastre', '/assets/exercises/0851-0lQnxMZ.webm', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.
Sostén un peso frente al pecho con ambas manos, o coloca una barra sobre la parte superior de la espalda.
Manteniendo el pecho elevado y el core activado, baja lentamente el cuerpo flexionando las rodillas y las caderas.
Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.
Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1326', 'Dominadas supinas', 'Espalda', 'Dorsales', 'Peso Corporal', '/assets/exercises/1326-T2mxWqc.webm', 'Cuélgate de una barra de dominadas con las palmas mirando hacia ti y las manos separadas a la altura de los hombros.
Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho.
Continúa subiendo hasta que la barbilla quede por encima de la barra.
Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0652', 'Dominadas', 'Espalda', 'Dorsales', 'Peso Corporal', '/assets/exercises/0652-lBDjFxJ.webm', 'Cuélgate de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos.
Activa el core y junta los omóplatos.
Tira de tu cuerpo hacia la barra flexionando los codos y llevando el pecho hacia la barra.
Haz una pausa en la parte alta del movimiento y luego baja lentamente el cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3418', 'L-pull-up', 'Espalda', 'Dorsales', 'Peso Corporal', '/assets/exercises/3418-d1GgzTU.webm', 'Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.
Cuélgate con los brazos completamente extendidos y el cuerpo recto.
Activa los dorsales y los bíceps para llevar el cuerpo hacia arriba en dirección a la barra, manteniendo los codos cerca del cuerpo.
Continúa subiendo hasta que la barbilla quede por encima de la barra.
Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0631', 'Muscle up', 'Espalda', 'Dorsales', 'Peso Corporal', '/assets/exercises/0631-yJUHKTn.webm', 'Comienza colgándote de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos.
Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho.
Al llegar a la parte alta del movimiento, cambia el agarre de modo que las palmas queden hacia ti.
Sigue tirando hacia arriba hasta que el pecho quede por encima de la barra y los brazos estén completamente flexionados.
Invierte el movimiento bajando lentamente de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0670', 'Rear pull-up', 'Espalda', 'Dorsales', 'Peso Corporal', '/assets/exercises/0670-CbFSYC1.webm', 'Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.
Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.
Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo.
Continúa subiendo hasta que la barbilla quede por encima de la barra.
Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3293', 'Archer pull up', 'Espalda', 'Dorsales', 'Peso Corporal', '/assets/exercises/3293-72BC5Za.webm', 'Comienza colgándote de una barra de dominadas con un agarre prono, un poco más separado que el ancho de los hombros.
Activa el core y lleva los omóplatos hacia abajo y atrás.
Mientras te elevas, flexiona un brazo y lleva el codo hacia el costado, manteniendo el otro brazo recto.
Continúa subiendo hasta que la barbilla quede por encima de la barra y el brazo flexionado esté completamente doblado.
Bájate de nuevo con control, estirando el brazo flexionado y repitiendo el movimiento del otro lado.
Alterna los lados en cada repetición.'),
  ('3019', 'Bench pull-ups', 'Espalda', 'Dorsales', 'Peso Corporal', '/assets/exercises/3019-mExgrF9.webm', 'Colócate debajo de una barra o una superficie horizontal resistente que esté a la altura del pecho.
Sujeta la barra o la superficie con agarre prono, un poco más separado que el ancho de los hombros.
Cuélgate con los brazos completamente extendidos y el cuerpo recto.
Lleva el pecho hacia la barra o la superficie juntando los omóplatos y flexionando los codos.
Continúa tirando hasta que la barbilla quede por encima de la barra o la superficie.
Baja de nuevo a la posición inicial con control.
Repite el número de repeticiones deseado.'),
  ('0198', 'Jalón al pecho en polea', 'Espalda', 'Dorsales', 'Polea', '/assets/exercises/0198-RVwzP10.webm', 'Ajusta la máquina de jalón de cable de modo que el asiento quede a una altura cómoda y la almohadilla de rodillas esté asegurada.
Siéntate con la espalda recta y los pies apoyados planos en el suelo.
Sujeta la barra del cable con un agarre prono, un poco más separado que el ancho de los hombros.
Inclínate ligeramente hacia atrás y activa el core.
Jala la barra del cable hacia el pecho, apretando los omóplatos entre sí.
Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('2285', 'Pullover en máquina', 'Espalda', 'Dorsales', 'Máquina de Palanca', '/assets/exercises/2285-4U7iLb5.webm', 'Ajusta el asiento y las asas de la máquina de palanca a una posición cómoda.
Siéntate en la máquina con la espalda apoyada en la almohadilla y sujeta las asas con un agarre prono.
Mantén los brazos ligeramente flexionados y el core activado.
Tira lentamente de las asas hacia el pecho, apretando los dorsales.
Haz una pausa breve en el punto máximo de contracción, luego vuelve lentamente a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0638', 'A un brazo chin-up', 'Espalda', 'Dorsales', 'Peso Corporal', '/assets/exercises/0638-HjdqmZa.webm', 'Ponte de pie frente a una barra de dominadas con los pies separados a la altura de los hombros.
Estírate y agarra la barra con un agarre supino, con una mano sujetando la barra y la otra sosteniendo la muñeca como apoyo.
Cuélgate de la barra con el brazo completamente extendido, manteniendo el cuerpo recto y el core activado.
Tira de tu cuerpo hacia la barra flexionando el codo y contrayendo los músculos de la espalda.
Continúa subiendo hasta que la barbilla quede por encima de la barra, luego bájate lentamente de vuelta a la posición inicial.
Repite el número de repeticiones deseado, luego cambia de brazo y repite.'),
  ('0017', 'Assisted pull-up', 'Espalda', 'Dorsales', 'Máquina de Palanca', '/assets/exercises/0017-kiJ4Z2K.webm', 'Ajusta la máquina a los valores de peso y altura deseados.
Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.
Cuélgate con los brazos completamente extendidos y los pies sin tocar el suelo.
Activa los músculos de la espalda y lleva el cuerpo hacia arriba hacia las agarraderas, manteniendo los codos cerca del cuerpo.
Continúa subiendo hasta que la barbilla quede por encima de las agarraderas.
Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1405', 'Back pec estiramiento', 'Espalda', 'Dorsales', 'Peso Corporal', '/assets/exercises/1405-chfnQnM.webm', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.
Extiende los brazos rectos frente a ti, paralelos al suelo.
Cruza los brazos frente al cuerpo, con el brazo derecho sobre el brazo izquierdo.
Entrelaza los dedos y gira las palmas alejándolas del cuerpo.
Levanta lentamente los brazos hacia arriba y alejándolos del cuerpo, sintiendo un estiramiento en la espalda y el pecho.
Mantén el estiramiento durante 15-30 segundos, luego suelta.
Repite del lado opuesto.'),
  ('0073', 'Pullover con barra', 'Espalda', 'Dorsales', 'Barra', '/assets/exercises/0073-i6LWjok.webm', 'Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.
Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho.
Manteniendo los brazos rectos, baja la barra detrás de la cabeza de forma controlada hasta sentir un estiramiento en los dorsales.
Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0841', 'Dominadas con lastre', 'Espalda', 'Dorsales', 'Con Lastre', '/assets/exercises/0841-HMzLjXx.webm', 'Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.
Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.
Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo.
Continúa subiendo hasta que la barbilla quede por encima de la barra.
Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0558', 'Kipping muscle up', 'Espalda', 'Dorsales', 'Peso Corporal', '/assets/exercises/0558-pM07UxU.webm', 'Comienza colgándote de una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.
Activa el core y usa un movimiento de balanceo para generar impulso.
Mientras te balanceas hacia adelante, tira del pecho hacia la barra, usando los dorsales y los bíceps para iniciar el movimiento.
Continúa el movimiento ascendente hasta que el pecho llegue a la barra, luego pasa a una posición de fondos empujando hacia abajo en la barra y extendiendo los brazos.
Bájate de vuelta a la posición inicial flexionando los brazos y controlando el descenso.
Repite el número de repeticiones deseado.'),
  ('1368', 'Ankle circles', 'Piernas', 'Gemelos', 'Peso Corporal', '/assets/exercises/1368-uL9CsKm.webm', 'Siéntate en el suelo con las piernas extendidas frente a ti.
Levanta una pierna del suelo y rota el tobillo con un movimiento circular.
Realiza el número de círculos deseado en una dirección, luego cambia a la dirección contraria.
Repite con la otra pierna.'),
  ('1396', 'Elevación de talones en multipower (Smith)', 'Piernas', 'Gemelos', 'Multipower (Smith)', '/assets/exercises/1396-Y4QlY8z.webm', 'Ajusta la barra de la máquina Smith a una altura que te permita pararte cómodamente con los pies planos sobre el suelo.
Colócate debajo de la barra con los hombros justo debajo de ella y los pies separados a la altura de los hombros.
Coloca la planta de los pies sobre una plataforma elevada o discos de peso, dejando los talones colgando fuera del borde.
Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.
Activa el core y mantén la espalda recta durante todo el ejercicio.
Levanta lentamente los talones lo más alto posible, elevando el peso de tu cuerpo sobre la punta de los pies.
Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1397', 'De pie gemelos', 'Piernas', 'Gemelos', 'Peso Corporal', '/assets/exercises/1397-XIHEoCG.webm', 'Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante.
Levanta los talones del suelo lo más alto posible, apoyándote sobre la punta de los pies.
Mantén la posición por un momento y luego baja lentamente los talones de nuevo a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('2289', 'Gemelos press en máquina', 'Piernas', 'Gemelos', 'Máquina de Palanca', '/assets/exercises/2289-7B4F5nZ.webm', 'Ajusta el asiento de la máquina de palanca de modo que los hombros queden alineados con la almohadilla de la palanca.
Coloca los dedos de los pies sobre la almohadilla de la palanca, con los talones colgando fuera del borde.
Sujeta las asas o los soportes laterales para mayor estabilidad.
Empuja la almohadilla de la palanca hacia abajo extendiendo los tobillos, contrayendo los músculos de las pantorrillas.
Haz una pausa por un momento en la parte baja del movimiento.
Vuelve lentamente a la posición inicial dejando que los talones se eleven de nuevo.
Repite el número de repeticiones deseado.'),
  ('0284', 'Donkey gemelos raise', 'Piernas', 'Gemelos', 'Peso Corporal', '/assets/exercises/0284-u5ESqzH.webm', 'Ponte de pie con las puntas de los pies sobre una superficie elevada, como un escalón o un bloque.
Coloca las manos en un soporte estable, como una pared o un pasamanos, para mantener el equilibrio.
Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies.
Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('2315', 'Rotary gemelos en máquina', 'Piernas', 'Gemelos', 'Máquina de Palanca', '/assets/exercises/2315-MrgP9L6.webm', 'Ajusta la altura del asiento de modo que las rodillas queden ligeramente flexionadas y los pies queden planos sobre la placa para los pies.
Coloca los dedos de los pies sobre la placa para los pies, con los talones colgando fuera del borde.
Sujeta las asas o los lados de la máquina para mayor estabilidad.
Empuja con la parte delantera de los pies, elevando los talones tan alto como sea posible.
Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0257', 'Circles knee estiramiento', 'Piernas', 'Gemelos', 'Peso Corporal', '/assets/exercises/0257-X7jbxra.webm', 'Ponte de pie con los pies separados a la altura de los hombros y las manos en las caderas.
Flexiona ligeramente las rodillas y levanta los talones del suelo, equilibrándote sobre las puntas de los pies.
Manteniendo las rodillas flexionadas, gira las rodillas en un movimiento circular, primero en el sentido de las agujas del reloj y luego en sentido contrario.
Realiza el movimiento el número de repeticiones deseado.'),
  ('1253', 'Donkey gemelos raise en máquina', 'Piernas', 'Gemelos', 'Máquina de Palanca', '/assets/exercises/1253-C9LuR4A.webm', 'Ajusta la máquina de palanca a la altura adecuada para tu cuerpo.
Colócate de frente a la máquina, con los dedos de los pies en la plataforma y los talones colgando fuera del borde.
Coloca las manos en las asas o en las barras de soporte para mayor estabilidad.
Activa las pantorrillas y levanta los talones tan alto como sea posible, usando la parte delantera de los pies.
Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0662', 'Flexiones', 'Pecho', 'Pectorales', 'Peso Corporal', '/assets/exercises/0662-I4hDWkc.webm', 'Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos.
Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo el cuerpo en línea recta.
Haz una pausa cuando el pecho esté justo por encima del suelo y luego empújate de vuelta a la posición inicial estirando los brazos.
Repite el número de repeticiones deseado.'),
  ('0251', 'Chest fondos', 'Pecho', 'Pectorales', 'Peso Corporal', '/assets/exercises/0251-9WTm7dq.webm', 'Colócate en las barras paralelas con los brazos completamente extendidos y el cuerpo recto.
Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos.
Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.
Repite el número de repeticiones deseado.'),
  ('3288', 'Fondos coreanos', 'Pecho', 'Pectorales', 'Peso Corporal', '/assets/exercises/3288-rWoBmi5.webm', 'Colócate entre dos barras paralelas con los brazos extendidos sosteniendo el peso de tu cuerpo.
Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.
Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.
Repite el número de repeticiones deseado.'),
  ('1273', 'Clap flexiones', 'Pecho', 'Pectorales', 'Peso Corporal', '/assets/exercises/1273-wigSg76.webm', 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros.
Baja el cuerpo hacia el suelo flexionando los codos, manteniendo el core activado.
Empuja con las palmas de forma explosiva para impulsar tu cuerpo fuera del suelo.
Mientras estás en el aire, junta las manos en un aplauso antes de aterrizar de vuelta en la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1274', 'Deep flexiones', 'Pecho', 'Pectorales', 'Mancuernas', '/assets/exercises/1274-vptOQ4N.webm', 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta.
Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.
Empuja con las palmas para extender los brazos y regresar a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1275', 'Drop flexiones', 'Pecho', 'Pectorales', 'Peso Corporal', '/assets/exercises/1275-Q497lAE.webm', 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros.
Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.
Una vez que tu pecho esté justo por encima del suelo, baja rápidamente las rodillas al suelo.
Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos.
Repite el número de repeticiones deseado.'),
  ('0308', 'Aperturas con mancuernas', 'Pecho', 'Pectorales', 'Mancuernas', '/assets/exercises/0308-yz9nUhF.webm', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.
Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos.
Manteniendo una ligera flexión en los codos, baja los brazos hacia los lados en un amplio arco hasta sentir un estiramiento en el pecho.
Haz una pausa por un momento, luego invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1306', 'Plyo flexiones', 'Pecho', 'Pectorales', 'Peso Corporal', '/assets/exercises/1306-Snj1wSv.webm', 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros.
Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo en línea recta.
Empuja explosivamente contra el suelo, usando los músculos del pecho para impulsar la parte superior del cuerpo fuera del suelo.
Aterriza suavemente con las manos de vuelta en la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3145', 'Flexiones plus', 'Pecho', 'Pectorales', 'Peso Corporal', '/assets/exercises/3145-pvBMLHA.webm', 'Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones.
Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.
Cuando el pecho esté justo por encima del suelo, empuja con las manos para extender los brazos y levantar la parte superior del cuerpo.
En la parte alta del movimiento, separa las escápulas empujando la parte superior de la espalda hacia el techo.
Haz una pausa por un momento y luego invierte el movimiento juntando las escápulas y bajando el cuerpo de nuevo a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0179', 'Bajo aperturas en polea', 'Pecho', 'Pectorales', 'Polea', '/assets/exercises/0179-FVmZVhk.webm', 'Sujeta las agarraderas a las poleas bajas de una máquina de cable y selecciona un peso adecuado.
Ponte de pie en el centro de la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.
Sujeta las agarraderas con un agarre prono y extiende los brazos hacia los lados, manteniendo una ligera flexión en los codos.
Manteniendo el control, lleva lentamente los brazos hacia adelante con un movimiento amplio, cruzándolos frente al cuerpo.
Haz una pausa por un momento en el punto más alto del movimiento, sintiendo el estiramiento en los músculos del pecho.
Invierte el movimiento y regresa lentamente los brazos a la posición inicial, manteniendo la tensión en los músculos del pecho durante todo el recorrido.
Repite el número de repeticiones deseado.'),
  ('0258', 'Clock flexiones', 'Pecho', 'Pectorales', 'Peso Corporal', '/assets/exercises/0258-CMAxnsG.webm', 'Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.
Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.
Mientras bajas, gira el cuerpo hacia la izquierda, extendiendo el brazo izquierdo recto hacia el lado.
Empuja de vuelta hacia arriba hasta la posición inicial, mientras giras el cuerpo hacia el centro.
Repite la flexión de brazos, esta vez girando el cuerpo hacia la derecha y extendiendo el brazo derecho hacia el lado.
Continúa alternando lados en cada repetición.'),
  ('3294', 'Archer flexiones', 'Pecho', 'Pectorales', 'Peso Corporal', '/assets/exercises/3294-A9qxk2F.webm', 'Comienza en posición de flexión de brazos con las manos un poco más separadas que el ancho de los hombros.
Extiende un brazo hacia el lado, paralelo al suelo.
Baja el cuerpo flexionando los codos, manteniendo la espalda recta y el core activado.
Empuja hacia arriba para volver a la posición inicial.
Repite del otro lado, extendiendo el brazo opuesto hacia el lado.
Continúa alternando lados durante el número de repeticiones deseado.'),
  ('0659', 'Flexiones (wall)', 'Pecho', 'Pectorales', 'Peso Corporal', '/assets/exercises/0659-LEH9jxP.webm', 'Ponte de pie frente a una pared, a una distancia aproximada de un brazo.
Coloca las manos en la pared a la altura de los hombros, un poco más separadas que la anchura de los hombros.
Da un paso atrás, manteniendo el cuerpo recto y los pies separados a la altura de las caderas.
Flexiona los codos y baja el pecho hacia la pared, manteniendo el cuerpo en línea recta.
Empuja de vuelta a la posición inicial, estirando los brazos.
Repite el número de repeticiones deseado.'),
  ('0185', 'Tumbado aperturas en polea', 'Pecho', 'Pectorales', 'Polea', '/assets/exercises/0185-lJJ7Yq8.webm', 'Sujeta las agarraderas a los cables y túmbate boca arriba en un banco con los pies apoyados planos en el suelo.
Sujeta las agarraderas con las palmas una frente a la otra y los brazos extendidos rectos por encima del pecho.
Manteniendo una ligera flexión en los codos, baja los brazos hacia los lados en un amplio arco hasta sentir un estiramiento en el pecho.
Haz una pausa por un momento y luego aprieta los músculos del pecho para regresar los brazos a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0279', 'Declinado flexiones', 'Pecho', 'Pectorales', 'Peso Corporal', '/assets/exercises/0279-i5cEhka.webm', 'Coloca las manos en el suelo un poco más separadas que el ancho de los hombros, con los pies elevados sobre una superficie estable.
Mantén el cuerpo en línea recta de la cabeza a los pies, activando los músculos del core.
Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.
Empuja con las palmas para extender los brazos y regresar a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0493', 'Inclinado flexiones', 'Pecho', 'Pectorales', 'Peso Corporal', '/assets/exercises/0493-B1EVP9F.webm', 'Coloca las manos sobre una superficie elevada, como un banco o un escalón, ligeramente más separadas que la altura de los hombros.
Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones.
Baja el pecho hacia la superficie elevada doblando los codos, manteniendo el cuerpo en línea recta.
Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.
Repite el número de repeticiones deseado.'),
  ('1254', 'Press de banca con banda', 'Pecho', 'Pectorales', 'Bandas Elásticas', '/assets/exercises/1254-khlHMqs.webm', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.
Agarra las agarraderas de la banda con un agarre prono, un poco más separadas que el ancho de los hombros.
Extiende los brazos por completo, empujando las bandas alejándolas del pecho.
Baja lentamente las bandas de vuelta hacia el pecho, manteniendo los codos en un ángulo de 90 grados.
Repite el número de repeticiones deseado.'),
  ('0188', 'Medio aperturas en polea', 'Pecho', 'Pectorales', 'Polea', '/assets/exercises/0188-xLYSdtg.webm', 'Sujeta los cables a ambos lados de una máquina de cable a la altura del pecho.
Ponte de pie en el centro de la máquina con un pie ligeramente delante del otro.
Sujeta las agarraderas con un agarre prono y extiende los brazos hacia los lados.
Mantén una ligera flexión en los codos y conserva una leve inclinación hacia adelante.
Activa los músculos del pecho y lleva los brazos hacia adelante con un movimiento amplio.
Haz una pausa por un momento en el centro y luego regresa lentamente los brazos a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0500', 'Isometric wipers', 'Pecho', 'Pectorales', 'Peso Corporal', '/assets/exercises/0500-11wrviz.webm', 'Comienza acostado boca arriba en una esterilla o un banco.
Extiende los brazos hacia los lados, perpendiculares al cuerpo.
Activa el core y levanta ambas piernas del suelo, manteniéndolas juntas y rectas.
Baja lentamente las piernas hacia un lado, intentando tocar el suelo con los pies mientras mantienes el control.
Haz una pausa breve, luego usa el core para llevar las piernas de vuelta a la posición inicial.
Repite el movimiento, esta vez bajando las piernas hacia el lado opuesto.
Continúa alternando lados durante el número de repeticiones deseado.'),
  ('0596', 'Sentado aperturas en máquina', 'Pecho', 'Pectorales', 'Máquina de Palanca', '/assets/exercises/0596-v3xmPAR.webm', 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.
Agarra las asas con un agarre pronado y mantén los codos ligeramente flexionados.
Exhala y empuja las asas hacia adelante, juntándolas frente a tu pecho.
Haz una pausa por un momento, contrayendo los músculos del pecho.
Inhala y vuelve lentamente a la posición inicial, permitiendo que los músculos del pecho se estiren.
Repite el número de repeticiones deseado.'),
  ('0803', 'Superman flexiones', 'Pecho', 'Pectorales', 'Peso Corporal', '/assets/exercises/0803-4GqRrAk.webm', 'Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos.
Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.
Mientras bajas el cuerpo, levanta simultáneamente el brazo derecho y la pierna izquierda del suelo, extendiéndolos completamente.
Haz una pausa de un momento en la parte superior, luego baja el brazo y la pierna mientras te empujas de nuevo hacia arriba a la posición inicial.
Repite el movimiento, esta vez levantando el brazo izquierdo y la pierna derecha.
Continúa alternando lados durante el número de repeticiones deseado.'),
  ('0151', 'Press de banca en polea', 'Pecho', 'Pectorales', 'Polea', '/assets/exercises/0151-7xI5MXA.webm', 'Ajusta la máquina de cable a la altura del pecho y coloca las agarraderas.
Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.
Sujeta las agarraderas con agarre prono y da un paso hacia adelante para crear tensión en los cables.
Coloca los pies firmemente en el suelo y activa el core.
Flexiona los codos y lleva las manos a la altura de los hombros, manteniendo los codos en un ángulo de 90 grados.
Empuja las agarraderas hacia adelante, extendiendo completamente los brazos frente a ti.
Haz una pausa breve, luego invierte lentamente el movimiento, llevando las manos de vuelta a la altura de los hombros.
Repite el número de repeticiones deseado.'),
  ('0158', 'Declinado aperturas en polea', 'Pecho', 'Pectorales', 'Polea', '/assets/exercises/0158-7saC5zz.webm', 'Ajusta la máquina de cable a una posición declinada.
Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.
Sujeta las agarraderas con las palmas hacia adelante y los brazos extendidos rectos frente a ti.
Manteniendo una ligera flexión en los codos, abre los brazos hacia los lados con un movimiento controlado.
Haz una pausa breve en la posición completamente extendida, luego vuelve lentamente a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0171', 'Inclinado aperturas en polea', 'Pecho', 'Pectorales', 'Polea', '/assets/exercises/0171-tBWXbIT.webm', 'Ajusta la máquina de cable a una posición baja y sujeta las agarraderas.
Siéntate en un banco inclinado con la espalda apoyada en el respaldo y los pies planos en el suelo.
Sujeta las agarraderas con un agarre prono y extiende los brazos rectos frente a ti.
Manteniendo una ligera flexión en los codos, abre los brazos hacia los lados con un movimiento controlado.
Haz una pausa breve en la posición completamente extendida, luego vuelve lentamente a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0375', 'Pullover con mancuernas', 'Pecho', 'Pectorales', 'Mancuernas', '/assets/exercises/0375-9XjtHvS.webm', 'Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.
Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho.
Manteniendo una ligera flexión en los codos, baja lentamente la mancuerna detrás de la cabeza hasta sentir un estiramiento en el pecho y los hombros.
Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1004', 'Sentadilla con banda', 'Piernas', 'Glúteos', 'Bandas Elásticas', '/assets/exercises/1004-TUZLh71.webm', 'Ponte de pie con los pies separados a la altura de los hombros, con la banda colocada justo por encima de las rodillas.
Manteniendo el pecho arriba y el core activado, lleva las caderas hacia atrás y flexiona las rodillas para bajar a una posición de sentadilla.
Asegúrate de que las rodillas se alineen con los dedos de los pies y de que el peso recaiga en los talones.
Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0514', 'Jump sentadilla', 'Piernas', 'Glúteos', 'Peso Corporal', '/assets/exercises/0514-LIlE5Tn.webm', 'Ponte de pie con los pies separados a la altura de los hombros.
Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.
Salta de forma explosiva desde el suelo, extendiendo las caderas, las rodillas y los tobillos.
Mientras estás en el aire, lleva rápidamente los brazos hacia adelante para mantener el equilibrio.
Aterriza suavemente sobre la punta de los pies y pasa de inmediato a la siguiente repetición.
Repite el número de repeticiones deseado.'),
  ('0770', 'Sentadilla en multipower (Smith)', 'Piernas', 'Glúteos', 'Multipower (Smith)', '/assets/exercises/0770-jFtipLl.webm', 'Configura la máquina Smith con la barra a una altura adecuada para tu sentadilla.
Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.
Colócate debajo de la barra, apoyándola en la parte alta de los trapecios y los hombros.
Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.
Activa el core y suelta la barra del soporte, dando un paso atrás para alejarte del soporte.
Manteniendo el pecho elevado y la espalda recta, inicia la sentadilla doblando las caderas y las rodillas.
Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo.
Haz una pausa por un momento en la posición baja, luego empuja con los talones para volver a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1008', 'Step-up con banda', 'Piernas', 'Glúteos', 'Bandas Elásticas', '/assets/exercises/1008-d5bTEPV.webm', 'Coloca una banda alrededor de los muslos, justo por encima de las rodillas.
Ponte de pie frente a un escalón o plataforma con los pies separados a la altura de las caderas.
Sube a la plataforma con el pie derecho, empujando con el talón.
Extiende la pierna izquierda hacia atrás, manteniéndola recta.
Baja el pie izquierdo de nuevo hasta el suelo.
Repite subiendo a la plataforma con el pie izquierdo.
Continúa alternando las piernas durante el número de repeticiones deseado.'),
  ('0628', 'Monster walk', 'Piernas', 'Glúteos', 'Peso Corporal', '/assets/exercises/0628-O95afRA.webm', 'Coloca una banda elástica alrededor de los tobillos.
Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.
Da un paso hacia el lado con el pie derecho, manteniendo la tensión en la banda elástica.
Continúa con el pie izquierdo, dando un paso lateral para volver a la posición inicial.
Repite el número de repeticiones deseado, luego cambia de lado.'),
  ('1408', 'Elevación de cadera con banda', 'Piernas', 'Glúteos', 'Bandas Elásticas', '/assets/exercises/1408-E4R8Hz1.webm', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.
Coloca una banda elástica justo por encima de las rodillas.
Activa los glúteos y los músculos del core.
Presiona los talones contra el suelo y levanta las caderas del suelo, apretando los glúteos en la parte superior.
Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0054', 'Zancada con barra', 'Piernas', 'Glúteos', 'Barra', '/assets/exercises/0054-t8iSghb.webm', 'Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda.
Da un paso hacia delante con el pie derecho, manteniendo el torso erguido.
Baja el cuerpo flexionando la rodilla derecha hasta que el muslo quede paralelo al suelo.
Empuja con el talón derecho para regresar a la posición inicial.
Repite con la pierna izquierda, alternando las piernas el número de repeticiones deseado.'),
  ('3769', 'Curtsey sentadilla', 'Piernas', 'Glúteos', 'Peso Corporal', '/assets/exercises/3769-gUjqdei.webm', 'Ponte de pie con los pies separados a la altura de los hombros.
Da un paso en diagonal hacia atrás y a través de tu cuerpo con el pie derecho, cruzándolo detrás de la pierna izquierda.
Flexiona ambas rodillas como si hicieras una reverencia, bajando el cuerpo hacia el suelo.
Mantén el torso erguido y el peso sobre el pie delantero.
Empuja con el pie delantero para regresar a la posición inicial.
Repite en el otro lado, dando un paso en diagonal hacia atrás y a través de tu cuerpo con el pie izquierdo.'),
  ('0459', 'Flutter kicks', 'Piernas', 'Glúteos', 'Peso Corporal', '/assets/exercises/0459-UVo2Qs2.webm', 'Túmbate boca arriba con las piernas extendidas y las manos a los costados.
Activa el core y levanta las piernas del suelo unos 15 centímetros.
Manteniendo las piernas rectas, alterna levantando una pierna ligeramente más alto que la otra.
Continúa este movimiento de aleteo durante el número de repeticiones deseado.'),
  ('1476', 'A una pierna sentadilla', 'Piernas', 'Glúteos', 'Peso Corporal', '/assets/exercises/1476-C31LMnP.webm', 'Ponte de pie con los pies separados a la altura de los hombros.
Extiende una pierna hacia adelante, manteniéndola elevada del suelo.
Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla.
Mantén el pecho arriba y la espalda recta.
Empuja con el talón para regresar a la posición inicial.
Repite con la otra pierna.'),
  ('1460', 'Walking zancada', 'Piernas', 'Glúteos', 'Peso Corporal', '/assets/exercises/1460-IZVHb27.webm', 'Ponte de pie con los pies separados a la altura de los hombros.
Da un paso adelante con la pierna derecha, bajando el cuerpo a una posición de zancada.
Mantén el torso erguido y la rodilla delantera alineada con el tobillo.
Empújate con el pie derecho y lleva el pie izquierdo hacia adelante, entrando en una posición de zancada con la pierna izquierda.
Continúa alternando las piernas y avanzando, manteniendo un ritmo controlado y constante.
Repite el número de repeticiones deseado.'),
  ('1003', 'Sentadilla remo con banda', 'Piernas', 'Glúteos', 'Bandas Elásticas', '/assets/exercises/1003-w1NOByi.webm', 'Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.
Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.
Sostén las agarraderas de la banda con las palmas mirándose entre sí y los brazos extendidos frente a ti.
Flexiona las rodillas y baja a una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.
Desde la posición de sentadilla, tira de las agarraderas de la banda hacia el cuerpo, juntando los omóplatos.
Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0157', 'Peso muerto en polea', 'Piernas', 'Glúteos', 'Polea', '/assets/exercises/0157-eGDudUV.webm', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.
Flexiona las caderas y las rodillas, bajando el torso hasta que la espalda quede paralela al suelo.
Sujeta las agarraderas del cable con agarre prono, manteniendo los brazos rectos y los hombros hacia atrás.
Activa los glúteos y los isquiotibiales para levantar las agarraderas del cable, extendiendo las caderas y poniéndote de pie.
Haz una pausa breve en la parte más alta, luego baja lentamente las agarraderas del cable de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0295', 'Clean con mancuernas', 'Piernas', 'Glúteos', 'Mancuernas', '/assets/exercises/0295-7Hg55JG.webm', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.
Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.
Extiende las caderas y las rodillas de forma explosiva, empujando con los talones para saltar del suelo.
Mientras saltas, encoge los hombros y tira de las mancuernas hacia arriba, hacia los hombros, manteniéndolas cerca del cuerpo.
Atrapa las mancuernas a la altura de los hombros, con los codos apuntando hacia adelante y las palmas hacia arriba.
Baja las mancuernas de vuelta a la posición inicial invirtiendo el movimiento.
Repite el número de repeticiones deseado.'),
  ('0336', 'Zancada con mancuernas', 'Piernas', 'Glúteos', 'Mancuernas', '/assets/exercises/0336-RRWFUcw.webm', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.
Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.
Mantén la espalda recta y el pecho erguido mientras bajas el cuerpo.
Empuja con el talón derecho para regresar a la posición inicial.
Repite con la pierna izquierda.
Alterna las piernas el número de repeticiones deseado.'),
  ('0413', 'Sentadilla con mancuernas', 'Piernas', 'Glúteos', 'Mancuernas', '/assets/exercises/0413-HsvHqgf.webm', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados.
Manteniendo el pecho arriba y el core activado, baja el cuerpo flexionando las rodillas y las caderas, como si te sentaras en una silla.
Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.
Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0578', 'Peso muerto en máquina', 'Piernas', 'Glúteos', 'Máquina de Palanca', '/assets/exercises/0578-GUT8I22.webm', 'Ajusta la altura del asiento y la plataforma para los pies a la posición deseada.
Siéntate en la máquina con la espalda apoyada en la almohadilla y los pies planos sobre la plataforma para los pies.
Sujeta las asas o los lados del asiento para mayor estabilidad.
Activa los glúteos y los isquiotibiales, y empuja con los talones para levantar el peso.
Mantén la espalda recta y evita redondear los hombros.
Extiende por completo las caderas en la parte alta del movimiento, apretando los glúteos.
Baja el peso de manera controlada, manteniendo la tensión en los glúteos y los isquiotibiales.
Repite el número de repeticiones deseado.'),
  ('0752', 'Peso muerto en multipower (Smith)', 'Piernas', 'Glúteos', 'Multipower (Smith)', '/assets/exercises/0752-UfePqpx.webm', 'Configura la máquina Smith con la barra a la altura de la cadera.
Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.
Dobla las caderas y las rodillas, manteniendo la espalda recta y el pecho elevado, y sujeta la barra con un agarre prono un poco más ancho que los hombros.
Activa el core y levanta la barra extendiendo las caderas y las rodillas, manteniendo la barra cerca del cuerpo.
Ponte de pie erguido, extendiendo por completo las caderas y las rodillas.
Baja la barra de nuevo doblando las caderas y las rodillas, manteniendo el control y la espalda recta.
Repite el número de repeticiones deseado.'),
  ('1466', 'Twist elevación de cadera', 'Piernas', 'Glúteos', 'Peso Corporal', '/assets/exercises/1466-AX1kB0o.webm', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.
Coloca las manos a los lados para mayor apoyo.
Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros.
Manteniendo las caderas elevadas, gira la parte inferior del cuerpo hacia el lado derecho, llevando las rodillas hacia el suelo.
Vuelve a la posición inicial y repite el giro hacia el lado izquierdo.
Continúa alternando los giros el número de repeticiones deseado.'),
  ('0852', 'Sentadilla con lastre', 'Piernas', 'Glúteos', 'Con Lastre', '/assets/exercises/0852-JZuApnB.webm', 'Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.
Sostén un peso frente al pecho o sobre los hombros.
Activa el core y mantén el pecho elevado mientras bajas las caderas hacia abajo y hacia atrás, como si te sentaras en una silla.
Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.
Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte superior.
Repite el número de repeticiones deseado.'),
  ('0137', 'Body-up', 'Brazos', 'Tríceps', 'Peso Corporal', '/assets/exercises/0137-U6G2gk9.webm', 'Comienza colocando las manos sobre una superficie elevada, como un banco o unas barras paralelas, con las palmas hacia abajo y los dedos apuntando hacia adelante.
Extiende las piernas frente a ti, manteniendo los talones en el suelo y el cuerpo recto.
Baja el cuerpo flexionando los codos, manteniéndolos cerca del cuerpo, hasta que los brazos superiores queden paralelos al suelo.
Haz una pausa breve, luego empuja con las palmas para extender los brazos y levantar el cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3302', 'Handstand', 'Brazos', 'Tríceps', 'Peso Corporal', '/assets/exercises/3302-XooAdhl.webm', 'Busca un espacio abierto con suficiente espacio para hacer un pino.
Coloca las manos en el suelo separadas a la altura de los hombros, con los dedos apuntando hacia adelante.
Lanza las piernas hacia la pared, usando el core y los hombros para mantener el equilibrio.
Una vez en posición de pino, activa los tríceps para sostener el peso corporal.
Mantén el pino el mayor tiempo posible mientras conserves el equilibrio.
Para bajar, lleva lentamente las piernas de vuelta al suelo.
Repite el número de repeticiones deseado.'),
  ('0677', 'Ring fondos', 'Brazos', 'Tríceps', 'Peso Corporal', '/assets/exercises/0677-ezTvXcr.webm', 'Comienza colgándote de las anillas con los brazos completamente extendidos y el cuerpo recto.
Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos.
Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.
Repite el número de repeticiones deseado.'),
  ('3287', 'Elbow fondos', 'Brazos', 'Tríceps', 'Peso Corporal', '/assets/exercises/3287-LkoAWAE.webm', 'Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas.
Desliza las caderas hacia adelante, fuera del banco, y estira las piernas, manteniendo los talones en el suelo.
Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.
Haz una pausa por un momento en la posición más baja, luego empuja con las manos para enderezar los brazos y levantar el cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0639', 'A un brazo fondos', 'Brazos', 'Tríceps', 'Peso Corporal', '/assets/exercises/0639-FAoIFMw.webm', 'Ponte de pie de espaldas a un banco o silla, con los pies separados a la altura de los hombros.
Coloca una mano en el banco o silla detrás de ti, con los dedos apuntando hacia tu cuerpo.
Extiende las piernas hacia adelante, manteniendo los talones en el suelo.
Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco o silla.
Haz una pausa por un momento en la parte baja y luego empuja con las palmas para estirar los brazos y volver a la posición inicial.
Repite el número de repeticiones deseado, luego cambia de lado y repite con el otro brazo.'),
  ('0672', 'Invertido fondos', 'Brazos', 'Tríceps', 'Peso Corporal', '/assets/exercises/0672-NZ5Qqkz.webm', 'Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo recto.
Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.
Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.
Repite el número de repeticiones deseado.'),
  ('0814', 'Triceps fondos', 'Brazos', 'Tríceps', 'Peso Corporal', '/assets/exercises/0814-X6C6i5Y.webm', 'Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante.
Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.
Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.
Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0717', 'Side flexiones', 'Brazos', 'Tríceps', 'Peso Corporal', '/assets/exercises/0717-wpbD28t.webm', 'Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.
Coloca la mano de abajo en el suelo directamente debajo del hombro, con los dedos apuntando hacia delante.
Empuja con la mano de abajo para levantar el cuerpo del suelo, manteniendo las piernas rectas y el core activado.
Extiende el brazo de arriba recto hacia el techo, formando una línea recta desde la cabeza hasta los talones.
Baja el cuerpo de nuevo a la posición inicial con control.
Repite el número de repeticiones deseado, luego cambia de lado.'),
  ('3291', 'Stalder press', 'Brazos', 'Tríceps', 'Peso Corporal', '/assets/exercises/3291-zd4P4B2.webm', 'Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos por encima de la cabeza.
Flexiona ligeramente las rodillas y activa el core.
Baja el cuerpo a una posición de sentadilla mientras mantienes los brazos extendidos por encima de la cabeza.
Mientras bajas en la sentadilla, empuja los brazos hacia el suelo, activando los tríceps.
Haz una pausa de un momento en la parte baja de la sentadilla, luego empuja con los talones para levantarte mientras al mismo tiempo elevas de nuevo los brazos por encima de la cabeza.
Repite el número de repeticiones deseado.'),
  ('0816', 'Triceps press', 'Brazos', 'Tríceps', 'Peso Corporal', '/assets/exercises/0816-fSrPP6B.webm', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.
Extiende los brazos rectos frente a ti, paralelos al suelo.
Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la parte superior de los brazos cerca de los costados.
Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0860', 'Patada de tríceps en polea', 'Brazos', 'Tríceps', 'Polea', '/assets/exercises/0860-HEJ6DIX.webm', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.
Sujeta la agarradera del cable con la mano derecha y retrocede un paso para crear tensión en el cable.
Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.
Mantén la parte superior del brazo cerca del cuerpo y el codo flexionado en un ángulo de 90 grados.
Extiende el antebrazo hacia atrás, enderezando el brazo por completo.
Haz una pausa por un momento, luego regresa lentamente a la posición inicial.
Repite el número de repeticiones deseado, luego cambia de lado.'),
  ('0201', 'Pushdown en polea', 'Brazos', 'Tríceps', 'Polea', '/assets/exercises/0201-3ZflifB.webm', 'Sujeta una barra recta a una máquina de cable con polea alta.
Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.
Sujeta la barra con un agarre prono, con las manos separadas a la altura de los hombros.
Mantén los codos cerca de los costados y los brazos superiores quietos.
Exhala y empuja la barra hacia abajo hasta que los codos queden completamente extendidos.
Haz una pausa por un momento, luego inhala y regresa lentamente la barra a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0283', 'Diamond flexiones', 'Brazos', 'Tríceps', 'Peso Corporal', '/assets/exercises/0283-soIB2rj.webm', 'Comienza en posición de plancha alta con las manos juntas, formando una figura de diamante con los pulgares y los índices.
Mantén el cuerpo en línea recta de la cabeza a los pies, activando el core y los glúteos.
Baja el pecho hacia la figura de diamante formada por tus manos, manteniendo los codos cerca del cuerpo.
Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3289', 'Fondos imposibles', 'Brazos', 'Tríceps', 'Peso Corporal', '/assets/exercises/3289-05Cf2v8.webm', 'Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo suspendido en el aire.
Flexiona las rodillas y cruza los tobillos.
Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.
Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.
Repite el número de repeticiones deseado.'),
  ('1753', 'Fondos entre tres bancos', 'Brazos', 'Tríceps', 'Peso Corporal', '/assets/exercises/1753-DQ0cqkT.webm', 'Siéntate en un banco con las manos agarrando el borde, los dedos apuntando hacia adelante.
Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.
Flexiona los codos y baja el cuerpo hasta que la parte superior de los brazos quede paralela al suelo.
Empújate de vuelta hacia arriba hasta la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0817', 'Triceps estiramiento', 'Brazos', 'Tríceps', 'Peso Corporal', '/assets/exercises/0817-uOV3Itw.webm', 'Ponte de pie o siéntate erguido con la espalda recta.
Extiende un brazo por encima de la cabeza, flexionándolo por el codo.
Coloca la mano opuesta sobre el codo flexionado y tira de él suavemente hacia tu cabeza.
Mantén el estiramiento de 15 a 30 segundos, sintiendo un estiramiento suave en el tríceps.
Suelta el estiramiento y repite con el otro brazo.'),
  ('0204', 'Rear drive en polea', 'Brazos', 'Tríceps', 'Polea', '/assets/exercises/0204-c3QQLPi.webm', 'Sujeta una agarradera a una máquina de cable con polea baja y ponte de pie de espaldas a la máquina.
Sujeta la agarradera con un agarre prono y extiende los brazos rectos frente a ti.
Manteniendo los codos inmóviles, jala la agarradera de vuelta hacia el cuerpo, apretando los tríceps al final del movimiento.
Regresa lentamente la agarradera a la posición inicial y repite el número de repeticiones deseado.'),
  ('1451', 'Sentado fondos en máquina', 'Brazos', 'Tríceps', 'Máquina de Palanca', '/assets/exercises/1451-BRImeP8.webm', 'Ajusta la altura del asiento de modo que tus pies queden planos en el suelo y tus rodillas formen un ángulo de 90 grados.
Agarra las asas de la máquina de palanca con las palmas hacia abajo y los brazos completamente extendidos.
Baja lentamente el cuerpo flexionando los codos hasta que tus brazos queden paralelos al suelo.
Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.
Repite el número de repeticiones deseado.'),
  ('0333', 'Patada de tríceps con mancuernas', 'Brazos', 'Tríceps', 'Mancuernas', '/assets/exercises/0333-W6PxUkg.webm', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.
Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.
Acerca los brazos superiores a los costados, con los codos flexionados en un ángulo de 90 grados.
Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento.
Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0471', 'Handstand flexiones', 'Brazos', 'Tríceps', 'Peso Corporal', '/assets/exercises/0471-rQxwMxO.webm', 'Busca una pared y colócate de espaldas a ella, de pie a unos pasos de distancia.
Coloca las manos en el suelo separadas a la altura de los hombros y lanza los pies hacia la pared, llegando a una posición de pino.
Dobla los codos y baja la cabeza hacia el suelo, manteniendo el cuerpo en línea recta.
Empuja con las manos y extiende los brazos para volver a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0685', 'Carrera', 'Cardio', 'Cardio', 'Peso Corporal', '/assets/exercises/0685-oLrKqDH.webm', 'Comienza de pie con los pies separados a la altura de la cadera.
Activa el core y mantén la parte superior del cuerpo relajada.
Comienza a trotar en el lugar, levantando las rodillas hacia el pecho y aterrizando suavemente sobre la punta de los pies.
Mantén un ritmo constante y continúa trotando durante la duración o distancia deseada.
Recuerda respirar profundamente y mantener una buena postura durante todo el ejercicio.'),
  ('1160', 'Burpee', 'Cardio', 'Cardio', 'Peso Corporal', '/assets/exercises/1160-dK9394r.webm', 'Comienza de pie con los pies separados a la altura de los hombros.
Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y colocando las manos en el suelo frente a ti.
Lleva los pies hacia atrás de una patada hasta una posición de flexión de brazos.
Realiza una flexión de brazos, manteniendo el cuerpo en línea recta.
Salta con los pies de vuelta a la posición de sentadilla.
Salta hacia arriba explosivamente, llevando los brazos por encima de la cabeza.
Aterriza suavemente y baja de inmediato a una posición de sentadilla para comenzar la siguiente repetición.'),
  ('3671', 'Ski step', 'Cardio', 'Cardio', 'Peso Corporal', '/assets/exercises/3671-5MRH8H2.webm', 'Ponte de pie con los pies separados a la altura de los hombros.
Dobla ligeramente las rodillas y mantén la espalda recta.
Salta hacia la derecha, aterrizando sobre el pie derecho mientras balanceas la pierna izquierda detrás de la pierna derecha.
Salta inmediatamente hacia la izquierda, aterrizando sobre el pie izquierdo mientras balanceas la pierna derecha detrás de la pierna izquierda.
Continúa alternando los saltos de lado a lado, imitando un movimiento de esquí.
Repite el número de repeticiones deseado.'),
  ('3318', 'Swing 360', 'Cardio', 'Cardio', 'Peso Corporal', '/assets/exercises/3318-tnaj0mT.webm', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.
Mantén los brazos extendidos rectos frente a ti, paralelos al suelo.
Activa el core y mueve los brazos en un movimiento circular, rotando el torso mientras lo haces.
Continúa el movimiento circular, moviendo los brazos y rotando el torso el número de repeticiones deseado.
Recuerda respirar durante todo el ejercicio.'),
  ('3637', 'Wheel run', 'Cardio', 'Cardio', 'Peso Corporal', '/assets/exercises/3637-km2Ljzj.webm', 'Comienza en posición de plancha con las manos sobre el rodillo y el cuerpo recto.
Activa el core y comienza a hacer rodar el rodillo hacia adelante extendiendo los brazos.
Continúa rodando hasta que tu cuerpo quede completamente extendido y los brazos por encima de la cabeza.
Invierte el movimiento tirando del rodillo de vuelta hacia tu cuerpo, usando el core y los brazos.
Repite el número de repeticiones deseado.'),
  ('3360', 'Paso del oso', 'Cardio', 'Cardio', 'Peso Corporal', '/assets/exercises/3360-0Yz8WdV.webm', 'Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas.
Levanta las rodillas ligeramente del suelo, manteniendo la espalda plana y el core activado.
Mueve la mano derecha y el pie izquierdo hacia adelante simultáneamente, seguido de la mano izquierda y el pie derecho.
Continúa avanzando a gatas, alternando los movimientos de manos y pies.
Mantén un ritmo constante y el core firme durante todo el ejercicio.
Continúa durante la distancia o el tiempo deseado.'),
  ('0501', 'Burpee con salto de tijera', 'Cardio', 'Cardio', 'Peso Corporal', '/assets/exercises/0501-mr7pkqP.webm', 'Comienza de pie con los pies separados a la altura de los hombros.
Baja el cuerpo a una posición de sentadilla, colocando las manos en el suelo frente a ti.
Lanza los pies hacia atrás, aterrizando en posición de flexión de brazos.
Realiza una flexión de brazos, bajando el pecho hacia el suelo y luego empujando de nuevo hacia arriba.
Salta con los pies hacia adelante, aterrizando en posición de sentadilla.
Salta hacia arriba explosivamente, llevando los brazos por encima de la cabeza.
Aterriza suavemente y baja de inmediato a una posición de sentadilla para comenzar la siguiente repetición.'),
  ('3638', 'Push to run', 'Cardio', 'Cardio', 'Peso Corporal', '/assets/exercises/3638-PrQbjvB.webm', 'Comienza en posición de flexión con las manos separadas a la altura de los hombros y el cuerpo en línea recta.
Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto.
Empuja con las manos para extender los brazos y volver a la posición inicial.
Lleva rápidamente una rodilla hacia el pecho, luego cambia rápidamente y lleva la otra rodilla hacia el pecho.
Continúa alternando las rodillas tan rápido como puedas manteniendo una buena forma.
Continúa durante el tiempo o el número de repeticiones deseado.'),
  ('3361', 'Saltos de patinador', 'Cardio', 'Cardio', 'Peso Corporal', '/assets/exercises/3361-zfNHMN9.webm', 'Ponte de pie con los pies separados a la altura de los hombros.
Dobla ligeramente las rodillas y salta hacia la derecha, aterrizando sobre el pie derecho.
Al aterrizar, balancea la pierna izquierda detrás de la pierna derecha y toca el suelo con los dedos del pie izquierdo.
Salta inmediatamente hacia la izquierda, aterrizando sobre el pie izquierdo.
Al aterrizar, balancea la pierna derecha detrás de la pierna izquierda y toca el suelo con los dedos del pie derecho.
Continúa alternando los lados, saltando y tocando el suelo con cada pierna.
Repite el número de repeticiones deseado.'),
  ('1201', 'Burpee con mancuernas', 'Cardio', 'Cardio', 'Mancuernas', '/assets/exercises/1201-0JtKWum.webm', 'Comienza de pie con los pies separados a la altura de los hombros y una mancuerna en cada mano.
Baja el cuerpo a una posición de sentadilla, colocando las mancuernas en el suelo frente a ti.
Lleva los pies hacia atrás a una posición de flexión de brazos, manteniendo el cuerpo en línea recta.
Realiza una flexión de brazos, flexionando los codos y bajando el pecho hacia el suelo.
Salta con los pies hacia tus manos, aterrizando en una posición de sentadilla.
Ponte de pie de forma explosiva, levantando las mancuernas del suelo y llevándolas a los hombros.
Empuja las mancuernas por encima de la cabeza, extendiendo completamente los brazos.
Baja las mancuernas de vuelta a los hombros y repite toda la secuencia el número de repeticiones deseado.'),
  ('3292', 'Elevator', 'Espalda', 'Espalda Alta', 'Peso Corporal', '/assets/exercises/3292-zYmNaoY.webm', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.
Coloca las manos sobre las caderas o crúzalas frente al pecho.
Manteniendo la espalda recta, inclínate lentamente hacia adelante desde la cintura, bajando la parte superior del cuerpo hacia el suelo.
Haz una pausa por un momento en la posición más baja, luego sube lentamente la parte superior del cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3297', 'Back lever', 'Espalda', 'Espalda Alta', 'Peso Corporal', '/assets/exercises/3297-GaSzzuh.webm', 'Comienza colgándote de una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.
Activa el core y lleva los omóplatos hacia abajo y atrás.
Flexiona las rodillas y llévalas hacia el pecho.
Levanta lentamente las piernas, manteniéndolas rectas, hasta que el cuerpo quede paralelo al suelo.
Mantén esta posición durante unos segundos, luego baja lentamente las piernas de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0499', 'Remo invertido', 'Espalda', 'Espalda Alta', 'Peso Corporal', '/assets/exercises/0499-bZGHsAZ.webm', 'Coloca una barra a la altura de la cintura o usa un entrenador de suspensión.
Ponte de pie frente a la barra o al entrenador de suspensión, con los pies separados a la altura de los hombros.
Agarra la barra o las asas con agarre prono, ligeramente más ancho que la altura de los hombros.
Inclínate hacia atrás, manteniendo el cuerpo recto y los talones en el suelo.
Tira del pecho hacia la barra o las asas, apretando los omóplatos entre sí.
Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3304', 'Skin the cat', 'Espalda', 'Espalda Alta', 'Peso Corporal', '/assets/exercises/3304-MSfvriJ.webm', 'Comienza colgándote de una barra con los brazos completamente extendidos y el cuerpo relajado.
Activa el core y levanta las piernas, llevando las rodillas hacia el pecho.
Continúa levantando las piernas por encima de la cabeza, permitiendo que el cuerpo pase entre los brazos.
Una vez que las piernas estén completamente extendidas por encima de la cabeza, comienza a bajarlas de nuevo hacia la posición inicial.
Mientras bajas las piernas, permite que el cuerpo pase de nuevo entre los brazos hasta quedar colgado con los brazos completamente extendidos otra vez.
Repite el número de repeticiones deseado.'),
  ('0808', 'Suspended remo', 'Espalda', 'Espalda Alta', 'Peso Corporal', '/assets/exercises/0808-4OaumBr.webm', 'Coloca un entrenador de suspensión a una altura adecuada.
Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.
Sostén las asas con un agarre prono, con las palmas mirándose entre sí.
Inclínate hacia atrás, manteniendo el cuerpo recto y los talones en el suelo.
Tira del pecho hacia las asas, apretando los omóplatos entre sí.
Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0581', 'Alto remo en máquina', 'Espalda', 'Espalda Alta', 'Máquina de Palanca', '/assets/exercises/0581-nZZZy9m.webm', 'Ajusta la altura del asiento y la plataforma para los pies a una posición cómoda.
Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la plataforma para los pies.
Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.
Mantén la espalda recta y activa el core.
Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.
Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1324', 'Upper remo en polea', 'Espalda', 'Espalda Alta', 'Polea', '/assets/exercises/1324-PQStVXH.webm', 'Sujeta una barra recta a una máquina de cable a la altura del pecho.
Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.
Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.
Mantén la espalda recta y el core activado.
Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí.
Haz una pausa breve en la parte alta del movimiento.
Suelta lentamente la barra de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0606', 'Remo en barra T en máquina', 'Espalda', 'Espalda Alta', 'Máquina de Palanca', '/assets/exercises/0606-aaXr7ld.webm', 'Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta.
Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies.
Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.
Mantén la espalda recta y activa el core.
Tira de las asas hacia el torso, juntando los omóplatos.
Haz una pausa en el punto de máxima contracción y luego suelta lentamente las asas hasta la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3669', 'De pie archer', 'Espalda', 'Espalda Alta', 'Peso Corporal', '/assets/exercises/3669-JF8AkMX.webm', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.
Extiende los brazos rectos hacia adelante a la altura de los hombros, paralelos al suelo.
Gira el torso hacia la derecha, manteniendo los brazos extendidos y la espalda recta.
Mientras giras, extiende el brazo derecho hacia adelante y el brazo izquierdo hacia atrás, imitando el movimiento de tensar un arco.
Mantén la posición por un momento y luego vuelve a la posición inicial.
Repite el movimiento, esta vez girando el torso hacia la izquierda y extendiendo el brazo izquierdo hacia adelante y el brazo derecho hacia atrás.
Continúa alternando lados durante el número de repeticiones deseado.'),
  ('0861', 'Remo sentado en polea', 'Espalda', 'Espalda Alta', 'Polea', '/assets/exercises/0861-fUBheHs.webm', 'Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.
Sujeta las agarraderas con un agarre prono, manteniendo la espalda recta y los hombros relajados.
Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.
Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3295', 'Front lever reps', 'Espalda', 'Espalda Alta', 'Peso Corporal', '/assets/exercises/3295-hbY9wqG.webm', 'Cuélgate de una barra de dominadas con agarre prono, palmas hacia afuera.
Activa el core y lleva los omóplatos hacia abajo y atrás.
Manteniendo el cuerpo recto, levanta las piernas hasta que queden paralelas al suelo.
Mantén esta posición todo el tiempo que puedas, intentando llegar a 10-20 segundos.
Baja lentamente las piernas de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1350', 'Remo sentado en máquina', 'Espalda', 'Espalda Alta', 'Máquina de Palanca', '/assets/exercises/1350-7I6LNUG.webm', 'Ajusta la altura del asiento y los apoyapiés a una posición cómoda.
Siéntate en la máquina con el pecho apoyado en la almohadilla y los pies sobre los apoyapiés.
Agarra las asas con un agarre prono, con las manos separadas a la altura de los hombros.
Mantén la espalda recta y el core activado.
Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.
Haz una pausa breve en la parte alta del movimiento.
Suelta lentamente las asas y vuelve a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0761', 'Narremo remo en multipower (Smith)', 'Espalda', 'Espalda Alta', 'Multipower (Smith)', '/assets/exercises/0761-JGKowMS.webm', 'Ajusta la altura del asiento y colócate en la máquina con los pies planos sobre el suelo.
Sujeta las asas con un agarre prono, un poco más estrecho que el ancho de los hombros.
Mantén la espalda recta y el pecho elevado mientras tiras de las asas hacia tu cuerpo, juntando las escápulas.
Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0497', 'Remo invertido v. 2', 'Espalda', 'Espalda Alta', 'Peso Corporal', '/assets/exercises/0497-uX3sUBz.webm', 'Coloca una barra a la altura de la cintura en una máquina Smith o usa un entrenador de suspensión.
Ponte de pie frente a la barra o al entrenador de suspensión y agárrala con agarre prono, manos separadas a la altura de los hombros.
Camina con los pies hacia adelante, inclinándote hacia atrás hasta que el cuerpo quede en un ligero ángulo.
Mantén el cuerpo recto y tira del pecho hacia la barra o las asas, apretando los omóplatos entre sí.
Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1773', 'A un brazo remo con toalla', 'Espalda', 'Espalda Alta', 'Peso Corporal', '/assets/exercises/1773-bKWbrTA.webm', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una toalla con una mano.
Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.
Extiende completamente el brazo, dejando que la toalla cuelgue frente a ti.
Tira de la toalla hacia el pecho, juntando los omóplatos.
Haz una pausa breve en la parte más alta, luego baja lentamente la toalla de vuelta a la posición inicial.
Repite el número de repeticiones deseado, luego cambia de brazo.'),
  ('0868', 'Curl en polea', 'Brazos', 'Bíceps', 'Polea', '/assets/exercises/0868-G08RZcQ.webm', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.
Sujeta el accesorio del cable con agarre supino, palmas hacia arriba.
Mantén los codos cerca de los costados y los brazos superiores quietos.
Exhala y flexiona el accesorio del cable hacia los hombros, contrayendo los bíceps.
Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.
Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0031', 'Curl con barra', 'Brazos', 'Bíceps', 'Barra', '/assets/exercises/0031-25GPyDY.webm', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas mirando hacia delante.
Mantén los codos cerca del torso y exhala mientras levantas el peso contrayendo los bíceps.
Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.
Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.
Inhala mientras comienzas a bajar lentamente la barra de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0140', 'Dominadas para bíceps', 'Brazos', 'Bíceps', 'Peso Corporal', '/assets/exercises/0140-guT8YnS.webm', 'Cuélgate de una barra de dominadas con las palmas mirando hacia afuera y las manos separadas a la altura de los hombros.
Activa el core y tira de tu cuerpo hacia arriba flexionando los codos, llevando el pecho hacia la barra.
Haz una pausa en la parte más alta del movimiento, luego baja lentamente de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1632', 'Curl de arrastre en polea', 'Brazos', 'Bíceps', 'Polea', '/assets/exercises/1632-dXz8zjF.webm', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.
Sujeta el accesorio del cable con agarre supino, palmas hacia arriba, y los brazos completamente extendidos.
Manteniendo los brazos superiores quietos, exhala y flexiona el accesorio del cable hacia los hombros contrayendo los bíceps.
Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.
Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos.
Repite el número de repeticiones deseado.'),
  ('0447', 'Curl con barra EZ', 'Brazos', 'Bíceps', 'Barra EZ', '/assets/exercises/0447-6TG6x2w.webm', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba.
Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento.
Exhala mientras subes la barra hacia los hombros, contrayendo los bíceps.
Haz una pausa breve en la parte más alta, luego inhala mientras bajas lentamente la barra de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0575', 'Curl de bíceps en máquina', 'Brazos', 'Bíceps', 'Máquina de Palanca', '/assets/exercises/0575-q6y3OhV.webm', 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.
Sujeta las asas con un agarre supino, con las palmas hacia arriba, y mantén los codos cerca de los costados.
Exhala y flexiona las asas hacia arriba, contrayendo los bíceps.
Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.
Inhala y baja lentamente los mangos de vuelta a la posición inicial, extendiendo completamente los brazos.
Repite el número de repeticiones deseado.'),
  ('0038', 'Curl de arrastre con barra', 'Brazos', 'Bíceps', 'Barra', '/assets/exercises/0038-IENzBdA.webm', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba.
Deja que la barra cuelgue a la longitud del brazo frente a los muslos.
Manteniendo los brazos superiores fijos, levanta la barra hacia el pecho contrayendo los bíceps.
Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1641', 'Curl sentado en polea', 'Brazos', 'Bíceps', 'Polea', '/assets/exercises/1641-8oYqOt9.webm', 'Siéntate en una máquina de cable con los pies apoyados planos en el suelo y la espalda recta.
Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos.
Manteniendo la parte superior de los brazos inmóvil, exhala y curva el accesorio del cable hacia los hombros, contrayendo los bíceps.
Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.
Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos.
Repite el número de repeticiones deseado.'),
  ('0190', 'A un brazo curl en polea', 'Brazos', 'Bíceps', 'Polea', '/assets/exercises/0190-YTur5nR.webm', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.
Sujeta la agarradera del cable con un agarre supino, con la palma hacia arriba.
Mantén el codo cerca del costado y curva lentamente el antebrazo hacia el hombro.
Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0206', 'Curl invertido en polea', 'Brazos', 'Bíceps', 'Polea', '/assets/exercises/0206-eOG0r6v.webm', 'Coloca una barra recta en una máquina de cable con polea baja.
Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.
Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.
Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.
Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps.
Haz una pausa breve en la parte alta, apretando los bíceps.
Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.
Repite el número de repeticiones deseado.'),
  ('1664', 'Alto curl con mancuernas', 'Brazos', 'Bíceps', 'Mancuernas', '/assets/exercises/1664-qAmNMJY.webm', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante.
Mantén los brazos superiores quietos y flexiona las mancuernas lo más alto posible contrayendo los bíceps.
Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1636', 'Overhead curl en polea', 'Brazos', 'Bíceps', 'Polea', '/assets/exercises/1636-wDUqY2u.webm', 'Sujeta una barra recta a una máquina de cable con polea alta.
Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.
Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.
Mantén los codos cerca de los costados y los brazos superiores quietos.
Exhala y curva la barra hacia la frente, manteniendo la parte superior de los brazos inmóvil.
Haz una pausa por un momento en la parte baja del movimiento, apretando los bíceps.
Inhala y regresa lentamente la barra a la posición inicial, extendiendo los brazos por completo.
Repite el número de repeticiones deseado.'),
  ('0195', 'Curl predicador en polea', 'Brazos', 'Bíceps', 'Polea', '/assets/exercises/0195-P2lNrGL.webm', 'Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho.
Siéntate en el banco scott y coloca la parte superior de los brazos sobre la almohadilla, agarrando el accesorio del cable con un agarre supino.
Mantén la espalda recta y los codos pegados a los costados.
Curva lentamente el accesorio del cable hacia los hombros, apretando los bíceps en la parte más alta del movimiento.
Haz una pausa por un momento y luego baja lentamente el accesorio del cable de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0592', 'Curl predicador en máquina', 'Brazos', 'Bíceps', 'Máquina de Palanca', '/assets/exercises/0592-b6hQYMb.webm', 'Ajusta la altura del asiento y colócate en la máquina de palanca.
Coloca los brazos superiores en la almohadilla y sujeta las asas con un agarre supino.
Mantén la espalda recta y los codos colocados sobre la almohadilla.
Exhala y flexiona los antebrazos hacia los brazos superiores, contrayendo los bíceps.
Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.
Inhala y baja lentamente las asas de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0080', 'Curl invertido con barra', 'Brazos', 'Bíceps', 'Barra', '/assets/exercises/0080-xNrS20v.webm', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.
Mantén los brazos superiores fijos y exhala mientras levantas la barra hacia arriba, contrayendo los bíceps.
Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.
Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.
Inhala mientras bajas lentamente la barra de vuelta a la posición inicial, manteniendo los brazos superiores fijos.
Repite el número de repeticiones deseado.'),
  ('1644', 'Sentadillating curl en polea', 'Brazos', 'Bíceps', 'Polea', '/assets/exercises/1644-3XFdb1Z.webm', 'Coloca un mango de cable en el ajuste más bajo de una máquina de cable.
Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.
Sujeta el mango del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos.
Baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y las rodillas detrás de las puntas de los pies.
Mientras te agachas, flexiona el mango del cable hacia los hombros, manteniendo los codos cerca de los costados.
Haz una pausa breve en la parte alta del movimiento, apretando los bíceps.
Baja lentamente el mango del cable de vuelta a la posición inicial, extendiendo completamente los brazos.
Repite el número de repeticiones deseado.'),
  ('0294', 'Curl de bíceps con mancuernas', 'Brazos', 'Bíceps', 'Mancuernas', '/assets/exercises/0294-NbVPDMW.webm', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.
Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.
Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.
Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.
Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0313', 'Curl martillo con mancuernas', 'Brazos', 'Bíceps', 'Mancuernas', '/assets/exercises/0313-slDvUAU.webm', 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.
Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante.
Esta será tu posición inicial.
Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps.
Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.
Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.
Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.
Repite el número de repeticiones recomendado.'),
  ('0391', 'Curl sentado con mancuernas', 'Brazos', 'Bíceps', 'Mancuernas', '/assets/exercises/0391-TiaZTxx.webm', 'Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, con las palmas hacia adelante.
Mantén la espalda recta y los codos cerca del torso.
Exhala y flexiona las mancuernas hacia los hombros, contrayendo los bíceps.
Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0070', 'Curl predicador con barra', 'Brazos', 'Bíceps', 'Barra', '/assets/exercises/0070-qOgPVf6.webm', 'Siéntate en un banco predicador con los brazos superiores apoyados en el cojín y el pecho contra el soporte.
Agarra la barra con un agarre supino, un poco más ancho que la separación de los hombros.
Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros.
Haz una pausa breve en la parte alta, apretando los bíceps.
Inhala y baja lentamente la barra de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1017', 'Elevación en Y con banda', 'Hombros', 'Deltoides', 'Bandas Elásticas', '/assets/exercises/1017-aHDy5O5.webm', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la banda frente a los muslos con las palmas mirando hacia adentro.
Mantén los brazos rectos y levántalos hacia arriba y hacia los lados, formando una ''Y'' con el cuerpo.
Junta los omóplatos en la parte superior del movimiento.
Baja lentamente los brazos de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0100', 'Skier con barra', 'Hombros', 'Deltoides', 'Barra', '/assets/exercises/0100-4Leypho.webm', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado.
Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.
Levanta simultáneamente la barra hacia los hombros mientras saltas ligeramente del suelo.
Al llegar a la parte más alta del movimiento, invierte rápidamente el movimiento y baja la barra de nuevo a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0376', 'Raise con mancuernas', 'Hombros', 'Deltoides', 'Mancuernas', '/assets/exercises/0376-c9MnDRp.webm', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo.
Mantén la espalda recta y activa el core.
Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos.
Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0978', 'Elevación frontal con banda', 'Hombros', 'Deltoides', 'Bandas Elásticas', '/assets/exercises/0978-TFA88iB.webm', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la banda frente a los muslos con las palmas hacia abajo.
Mantén los brazos rectos y levántalos lentamente hacia adelante hasta que queden paralelos al suelo.
Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0993', 'Pájaros (deltoides posterior) con banda', 'Hombros', 'Deltoides', 'Bandas Elásticas', '/assets/exercises/0993-sTfvVsG.webm', 'Sujeta la banda a un objeto fijo a la altura del pecho.
Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con ambas manos frente a ti.
Mantén los brazos rectos y levántalos hacia los lados hasta que queden paralelos al suelo.
Junta los omóplatos en la parte superior del movimiento.
Baja lentamente los brazos de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3305', 'Thruster con barra', 'Hombros', 'Deltoides', 'Barra', '/assets/exercises/3305-f7Y9eDZ.webm', 'Comienza de pie con los pies separados a la altura de los hombros, sujetando una barra a la altura de los hombros con agarre prono.
Baja a una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.
Al llegar a la parte más baja de la sentadilla, empuja explosivamente con los talones para ponerte de pie, presionando simultáneamente la barra por encima de la cabeza.
Baja la barra de nuevo a la altura de los hombros mientras vuelves a bajar a la posición de sentadilla.
Repite el número de repeticiones deseado.'),
  ('0438', 'W-press con mancuernas', 'Hombros', 'Deltoides', 'Mancuernas', '/assets/exercises/0438-vmwLyCg.webm', 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante.
Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante.
Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.
Baja las mancuernas de vuelta a la altura de los hombros.
Repite el número de repeticiones deseado.'),
  ('0162', 'Elevación frontal en polea', 'Hombros', 'Deltoides', 'Polea', '/assets/exercises/0162-u2X71Np.webm', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono.
Mantén la espalda recta y el core activado.
Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo.
Continúa levantando hasta que los brazos queden paralelos al suelo.
Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0246', 'Remo al mentón en polea', 'Hombros', 'Deltoides', 'Polea', '/assets/exercises/0246-cALKspW.webm', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta el accesorio del cable con un agarre prono.
Mantén la espalda recta y el core activado durante todo el ejercicio.
Tira del accesorio del cable directamente hacia arriba, hacia tu barbilla, guiando con los codos.
Haz una pausa breve en la parte alta, apretando los omóplatos entre sí.
Baja lentamente el accesorio del cable de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0378', 'Pájaros (deltoides posterior) con mancuernas', 'Hombros', 'Deltoides', 'Mancuernas', '/assets/exercises/0378-8DiFDVA.webm', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.
Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.
Extiende los brazos rectos hacia el suelo, con las palmas mirándose entre sí.
Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados y aprieta los omóplatos entre sí.
Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('2271', 'Left hook. boxing', 'Hombros', 'Deltoides', 'Peso Corporal', '/assets/exercises/2271-hoXt6wv.webm', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.
Mantén la mano izquierda arriba para proteger el rostro y la mano derecha junto a la barbilla.
Rota las caderas y pívota sobre el pie izquierdo mientras extiendes el brazo izquierdo hacia adelante con un movimiento de golpe.
Gira el torso y activa los músculos del core para generar potencia en el golpe.
Lleva el brazo rápidamente de vuelta a la posición inicial y repite el número de repeticiones deseado.'),
  ('0775', 'Remo al mentón en multipower (Smith)', 'Hombros', 'Deltoides', 'Multipower (Smith)', '/assets/exercises/0775-1DN3iz4.webm', 'Ponte de pie con los pies separados a la altura de los hombros, de frente a la máquina Smith.
Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.
Mantén la espalda recta y el core activado.
Tira de la barra hacia tu barbilla, guiando el movimiento con los codos.
Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0844', 'Round arm con lastre', 'Hombros', 'Deltoides', 'Con Lastre', '/assets/exercises/0844-VLYXo8S.webm', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.
Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.
Eleva los brazos hacia los lados, manteniendo una ligera flexión en los codos.
Continúa elevando los brazos hasta que queden paralelos al suelo.
Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0997', 'Shoulder press con banda', 'Hombros', 'Deltoides', 'Bandas Elásticas', '/assets/exercises/0997-peAeMR3.webm', 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.
Sostén la banda con las palmas hacia adelante y eleva las manos a la altura de los hombros, con los codos flexionados.
Empuja la banda por encima de la cabeza, extendiendo completamente los brazos.
Haz una pausa por un momento en la parte superior, luego baja lentamente la banda de vuelta a la altura de los hombros.
Repite el número de repeticiones deseado.'),
  ('0041', 'Elevación frontal con barra', 'Hombros', 'Deltoides', 'Barra', '/assets/exercises/0041-b2Uoz54.webm', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado.
Mantén los brazos rectos y levanta la barra hacia delante y hacia arriba hasta que alcance la altura de los hombros.
Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0120', 'Remo al mentón con barra', 'Hombros', 'Deltoides', 'Barra', '/assets/exercises/0120-UDlhcO8.webm', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros.
Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos.
Manteniendo la espalda recta y el core activado, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos.
Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0161', 'Forward raise en polea', 'Hombros', 'Deltoides', 'Polea', '/assets/exercises/0161-hvHhCv8.webm', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.
Sujeta la agarradera del cable con agarre prono, palmas hacia abajo, y los brazos completamente extendidos frente a ti.
Manteniendo los brazos rectos, levanta la agarradera del cable hasta la altura de los hombros.
Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0178', 'Elevación lateral en polea', 'Hombros', 'Deltoides', 'Polea', '/assets/exercises/0178-goJ6ezq.webm', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas del cable con un agarre prono.
Mantén los brazos rectos y el core activado.
Levanta los brazos hacia los lados hasta que queden paralelos al suelo.
Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0332', 'Iron cross con mancuernas', 'Hombros', 'Deltoides', 'Mancuernas', '/assets/exercises/0332-cALkHHX.webm', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados.
Levanta los brazos hacia los lados hasta que queden paralelos al suelo, formando una T con el cuerpo.
Haz una pausa por un momento, luego baja lentamente los brazos de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1700', 'Push press con mancuernas', 'Hombros', 'Deltoides', 'Mancuernas', '/assets/exercises/1700-FS63wTN.webm', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros.
Flexiona ligeramente las rodillas y baja el cuerpo, luego extiende las piernas de forma explosiva y presiona las mancuernas por encima de la cabeza.
Bloquea los brazos en la parte superior del movimiento, luego baja las mancuernas de vuelta a la altura de los hombros.
Repite el número de repeticiones deseado.'),
  ('0550', 'Thruster con pesa rusa', 'Hombros', 'Deltoides', 'Pesa Rusa (Kettlebell)', '/assets/exercises/0550-yWxMvB5.webm', 'Comienza de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos, con las palmas una frente a la otra.
Baja a una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás, manteniendo el pecho elevado y la espalda recta.
Al llegar a la parte baja de la sentadilla, empuja explosivamente con los talones para ponerte de pie, presionando al mismo tiempo la pesa rusa por encima de la cabeza.
Bloquea los brazos en la parte alta del movimiento, extendiendo los codos por completo.
Baja la pesa rusa de vuelta a la posición inicial invirtiendo el movimiento, flexionando los codos y bajando el peso de vuelta al pecho.
Repite el número de repeticiones deseado.'),
  ('0584', 'Elevación lateral en máquina', 'Hombros', 'Deltoides', 'Máquina de Palanca', '/assets/exercises/0584-dRTfGZT.webm', 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.
Sujeta las asas con un agarre prono y mantén los brazos rectos.
Exhala y levanta los brazos hacia los lados hasta que queden paralelos al suelo.
Haz una pausa breve en lo alto, luego inhala y baja lentamente los brazos de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0455', 'Curl de dedos', 'Antebrazos', 'Antebrazos', 'Barra', '/assets/exercises/0455-awG04cF.webm', 'Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, con las palmas hacia arriba.
Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.
Curva lentamente los dedos hacia las palmas, apretando la barra con fuerza.
Mantén la contracción por un momento, luego suelta lentamente los dedos hasta la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1428', 'Rotación de muñecas', 'Antebrazos', 'Antebrazos', 'Peso Corporal', '/assets/exercises/1428-2zNKRUB.webm', 'Extiende los brazos rectos frente a ti.
Cierra ambas manos en un puño.
Gira las muñecas en un movimiento circular, manteniendo los brazos quietos.
Continúa los círculos de muñeca el número de repeticiones deseado.'),
  ('0859', 'Wrist rollerer', 'Antebrazos', 'Antebrazos', 'Con Lastre', '/assets/exercises/0859-bd5b860.webm', 'Sujeta un peso a un extremo de una cuerda o barra.
Sostén el otro extremo de la cuerda o barra con ambas manos, con las palmas hacia abajo.
Ponte de pie con los pies separados a la altura de los hombros y los brazos completamente extendidos frente a ti.
Enrolla lentamente el peso hacia las manos flexionando las muñecas.
Haz una pausa breve en lo alto, luego baja lentamente el peso de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1016', 'Curl de muñeca con banda', 'Antebrazos', 'Antebrazos', 'Bandas Elásticas', '/assets/exercises/1016-vUTfFHw.webm', 'Siéntate en un banco o silla con los pies apoyados en el suelo.
Sujeta la banda con ambas manos, con las palmas hacia arriba, y apoya los antebrazos sobre los muslos.
Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos.
Haz una pausa por un momento en la parte superior, luego baja lentamente las muñecas de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0247', 'Curl de muñeca en polea', 'Antebrazos', 'Antebrazos', 'Polea', '/assets/exercises/0247-LrV4s90.webm', 'Coloca una barra recta en una máquina de cable con polea baja.
Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.
Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.
Apoya los antebrazos en un banco o almohadilla, con las muñecas colgando del borde.
Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.
Haz una pausa breve en la parte alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0126', 'Curl de muñeca con barra', 'Antebrazos', 'Antebrazos', 'Barra', '/assets/exercises/0126-82LxxkW.webm', 'Siéntate en un banco con los pies planos en el suelo y los antebrazos apoyados sobre los muslos, sujetando una barra con agarre supino.
Deja que la barra ruede hacia las puntas de los dedos, manteniendo las muñecas rectas.
Enrolla lentamente la barra hacia los antebrazos flexionando las muñecas.
Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('2288', 'Gripper hands en máquina', 'Antebrazos', 'Antebrazos', 'Máquina de Palanca', '/assets/exercises/2288-mKwcrHn.webm', 'Ajusta la altura del asiento y sujeta las asas de la máquina de palanca.
Mantén la espalda recta y los pies planos en el suelo.
Exhala y aprieta las asas, contrayendo los antebrazos.
Mantén la contracción durante un segundo, luego suelta lentamente y vuelve a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1437', 'Curl de dedos con mancuernas', 'Antebrazos', 'Antebrazos', 'Mancuernas', '/assets/exercises/1437-mtXengz.webm', 'Siéntate en un banco o silla con los pies apoyados en el suelo y la espalda recta.
Sostén una mancuerna en una mano con agarre supino, apoyando el antebrazo sobre el muslo, con la palma hacia arriba.
Deja que la mancuerna ruede hacia las puntas de los dedos, luego flexiona los dedos para volver a enrollarla hacia arriba.
Repite el número de repeticiones deseado, luego cambia a la otra mano.'),
  ('1018', 'Encogimiento de hombros con banda', 'Espalda', 'Trapecios', 'Bandas Elásticas', '/assets/exercises/1018-trmte8s.webm', 'Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies, sosteniendo los extremos con las manos.
Mantén los brazos rectos y relajados, y deja que la banda cuelgue frente a los muslos.
Activa los trapecios encogiendo los hombros hacia arriba, levantando la banda lo más alto posible.
Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0220', 'Encogimiento de hombros en polea', 'Espalda', 'Trapecios', 'Polea', '/assets/exercises/0220-Eg98Ft9.webm', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.
Sujeta las agarraderas del cable con un agarre prono y deja que los brazos cuelguen frente a ti.
Manteniendo los brazos rectos, encoge los hombros hacia las orejas.
Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0604', 'Encogimiento de hombros en máquina', 'Espalda', 'Trapecios', 'Máquina de Palanca', '/assets/exercises/0604-ZZKbeMw.webm', 'Ajusta la altura del asiento y colócate en la máquina de palanca con la espalda apoyada en la almohadilla.
Sujeta las asas con un agarre prono y mantén los brazos rectos.
Manteniendo la espalda recta, eleva los hombros hacia las orejas tan alto como sea posible.
Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0767', 'Encogimiento de hombros en multipower (Smith)', 'Espalda', 'Trapecios', 'Multipower (Smith)', '/assets/exercises/0767-OUQ0ZyW.webm', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.
Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.
Mantén los brazos rectos y los hombros relajados.
Levanta los hombros hacia las orejas, contrayendo los trapecios en la parte alta.
Mantén la posición por un momento y luego baja lentamente los hombros de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3012', 'Scapula fondos', 'Espalda', 'Trapecios', 'Peso Corporal', '/assets/exercises/3012-7xeukSt.webm', 'Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti.
Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.
Baja el cuerpo doblando los codos y retrayendo las escápulas, como si intentaras apretar un lápiz entre ellas.
Haz una pausa por un momento en la posición baja, luego empuja con las manos para extender los codos y volver a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0095', 'Encogimiento de hombros con barra', 'Espalda', 'Trapecios', 'Barra', '/assets/exercises/0095-dG7tG5y.webm', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a ti con un agarre pronado.
Mantén los brazos rectos y la espalda recta durante todo el ejercicio.
Levanta los hombros hacia las orejas lo más alto posible, apretando los trapecios en la parte alta.
Mantén la posición por un momento y luego baja lentamente los hombros de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0406', 'Encogimiento de hombros con mancuernas', 'Espalda', 'Trapecios', 'Mancuernas', '/assets/exercises/0406-NJzBsGJ.webm', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo.
Mantén los brazos rectos y deja que las mancuernas cuelguen a tus costados.
Eleva los hombros lo más alto posible, como si intentaras tocarte las orejas con ellos.
Mantén la contracción durante un segundo, luego baja lentamente los hombros de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0688', 'Scapular pull-up', 'Espalda', 'Trapecios', 'Peso Corporal', '/assets/exercises/0688-uTBt1HV.webm', 'Comienza colgándote de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos.
Retrae las escápulas llevándolas hacia abajo y atrás.
Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, enfocándote en juntar las escápulas.
Haz una pausa breve en la parte superior del movimiento, luego baja lentamente el cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1362', 'Esfinge', 'Espalda', 'Erectores Espinales', 'Peso Corporal', '/assets/exercises/1362-DIVyqrU.webm', 'Túmbate boca abajo en el suelo con los antebrazos planos sobre el piso y los codos justo debajo de los hombros.
Activa el core y levanta el pecho del suelo, manteniendo los antebrazos y los dedos de los pies en el piso.
Mantén esta posición durante unos segundos, asegurándote de mantener el cuello en una posición neutral.
Baja lentamente el pecho de nuevo a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1363', 'Spine estiramiento', 'Espalda', 'Erectores Espinales', 'Peso Corporal', '/assets/exercises/1363-JbC2iaV.webm', 'Siéntate en el suelo con las piernas extendidas frente a ti.
Coloca las manos en el suelo detrás de ti, con los dedos apuntando hacia tu cuerpo.
Activa el core e inclínate lentamente hacia atrás, manteniendo la espalda recta.
Sigue inclinándote hacia atrás hasta que sientas un estiramiento en la columna.
Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0489', 'Hyperextension', 'Espalda', 'Erectores Espinales', 'Peso Corporal', '/assets/exercises/0489-zhMwOwE.webm', 'Ajusta el banco de hiperextensiones para que la parte superior de los muslos quede apoyada en la almohadilla y los pies queden asegurados.
Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza.
Baja la parte superior del cuerpo hacia el suelo manteniendo la espalda recta.
Haz una pausa breve en la parte baja, luego eleva la parte superior del cuerpo hasta que quede alineada con las piernas.
Repite el número de repeticiones deseado.'),
  ('1352', 'Bajoer back curl', 'Espalda', 'Erectores Espinales', 'Peso Corporal', '/assets/exercises/1352-ANbbry2.webm', 'Túmbate boca abajo con las piernas extendidas y los brazos a los lados del cuerpo.
Activa los glúteos y los isquiotibiales, y eleva lentamente la parte superior del cuerpo del suelo, curvando la espalda hacia arriba.
Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1366', 'Perro boca arriba', 'Espalda', 'Erectores Espinales', 'Peso Corporal', '/assets/exercises/1366-01qpYSe.webm', 'Túmbate boca abajo en el suelo con las piernas extendidas detrás de ti.
Coloca las manos en el suelo junto a las costillas inferiores, con los dedos apuntando hacia adelante.
Presiona las manos firmemente contra el suelo y estira los brazos, levantando el torso y los muslos del suelo.
Lleva los hombros hacia atrás y hacia abajo, abriendo el pecho y elevando la mirada hacia el techo.
Mantén esta posición durante unas cuantas respiraciones, luego baja lentamente el cuerpo de nuevo a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0573', 'Extensión de espalda en máquina', 'Espalda', 'Erectores Espinales', 'Máquina de Palanca', '/assets/exercises/0573-rUXfn3R.webm', 'Ajusta la máquina según el tamaño de tu cuerpo y tu rango de movimiento.
Siéntate en la máquina con la espalda apoyada en la almohadilla y los pies asegurados.
Coloca las manos en las asas o en las barras de agarre.
Activa el core e inclínate lentamente hacia adelante, permitiendo que la espalda se redondee ligeramente.
Haz una pausa breve en la posición baja, sintiendo un estiramiento en la zona lumbar.
Usando los músculos de la espalda, levanta lentamente el torso de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1364', 'De pie pelvic tilt', 'Espalda', 'Erectores Espinales', 'Peso Corporal', '/assets/exercises/1364-cuKYxhu.webm', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.
Coloca las manos sobre las caderas o déjalas colgar a los lados.
Activa los músculos del core e inclina la pelvis hacia adelante, empujando la zona lumbar hacia la pared detrás de ti.
Mantén la posición durante unos segundos, luego suelta y vuelve a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3231', 'Two toque de puntas (male)', 'Espalda', 'Erectores Espinales', 'Peso Corporal', '/assets/exercises/3231-p195zsJ.webm', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.
Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas.
Estira los brazos hacia la punta de los pies con ambas manos, manteniendo las piernas rectas.
Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0648', 'Power clean', 'Piernas', 'Isquiotibiales', 'Barra', '/assets/exercises/0648-SiWCcTN.webm', 'Comienza con la barra en el suelo frente a ti, con los pies separados a la altura de los hombros.
Agáchate y agarra la barra con un agarre prono, un poco más separado que la anchura de los hombros.
Mantén la espalda recta y el pecho hacia arriba al levantar la barra del suelo, extendiendo las caderas y las rodillas.
Cuando la barra llegue a la mitad del muslo, tira de ella explosivamente hacia arriba, encogiendo los hombros y llevando los codos hacia arriba y hacia los lados.
Cuando la barra alcance su punto más alto, baja rápidamente debajo de ella, rotando los codos y atrapando la barra sobre los hombros en una posición de sentadilla frontal.
Ponte de pie con la barra, extendiendo completamente las caderas y las rodillas.
Baja la barra de nuevo a la posición inicial, manteniendo el control del peso durante todo el movimiento.
Repite el número de repeticiones deseado.'),
  ('0555', 'Kick out sit', 'Piernas', 'Isquiotibiales', 'Peso Corporal', '/assets/exercises/0555-v7p5bYl.webm', 'Siéntate en el borde de un banco o una silla con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.
Inclínate ligeramente hacia atrás y coloca las manos en el borde del banco o la silla como apoyo.
Activando los isquiotibiales, levanta los pies del suelo y extiende las piernas rectas hacia adelante.
Haz una pausa breve en lo alto, luego flexiona lentamente las rodillas y lleva los pies de vuelta hacia el cuerpo.
Repite el número de repeticiones deseado.'),
  ('3193', 'Elevación glúteo-femoral', 'Piernas', 'Isquiotibiales', 'Peso Corporal', '/assets/exercises/3193-Vvwjz6N.webm', 'Ajusta la máquina de extensión de glúteos e isquiotibiales para que se adapte a tu cuerpo.
Colócate boca abajo en la máquina con los tobillos asegurados.
Coloca las manos sobre el pecho o crúzalas sobre el pecho.
Activa los isquiotibiales y los glúteos para levantar la parte superior del cuerpo hacia el techo.
Continúa levantando hasta que el cuerpo forme una línea recta desde la cabeza hasta los talones.
Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1585', 'Runners estiramiento', 'Piernas', 'Isquiotibiales', 'Peso Corporal', '/assets/exercises/1585-0mB6wHO.webm', 'Ponte de pie con los pies separados a la altura de la cadera.
Da un paso hacia delante con el pie derecho, manteniendo el pie izquierdo firme en el suelo.
Dobla la rodilla derecha y baja el cuerpo, manteniendo la pierna izquierda recta.
Coloca las manos sobre el muslo derecho para apoyarte.
Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite.'),
  ('1511', 'Hamstring estiramiento', 'Piernas', 'Isquiotibiales', 'Peso Corporal', '/assets/exercises/1511-99rWm7w.webm', 'Ponte de pie con los pies separados a la altura de los hombros.
Da un paso adelante con el pie derecho y traslada el peso hacia la pierna derecha.
Manteniendo la espalda recta, inclínate lentamente hacia adelante desde las caderas, alcanzando el pie derecho con ambas manos.
Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial.
Repite del otro lado.'),
  ('0044', 'Good morning con barra', 'Piernas', 'Isquiotibiales', 'Barra', '/assets/exercises/0044-XlZ4lAC.webm', 'Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada sobre la parte superior de la espalda.
Manteniendo la espalda recta y el core activado, flexiona las caderas hacia delante, empujando los glúteos hacia atrás como si intentaras tocar la pared detrás de ti con ellos.
Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.
Haz una pausa breve y luego vuelve a la posición inicial apretando los glúteos y empujando las caderas hacia delante.
Repite el número de repeticiones deseado.'),
  ('0586', 'Tumbado curl femoral en máquina', 'Piernas', 'Isquiotibiales', 'Máquina de Palanca', '/assets/exercises/0586-17lJ1kr.webm', 'Ajusta la máquina a tu cuerpo y selecciona el peso deseado.
Túmbate boca abajo en la máquina con las piernas rectas y los talones contra la palanca acolchada.
Sujeta las asas o los lados de la máquina para mayor estabilidad.
Manteniendo la parte superior del cuerpo inmóvil, exhala y flexiona las piernas hacia arriba tanto como sea posible sin levantar las caderas de la almohadilla.
Mantén la posición contraída durante una pausa breve mientras aprietas los isquiotibiales.
Inhala y baja lentamente la palanca de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0535', 'Hang clean con pesa rusa', 'Piernas', 'Isquiotibiales', 'Pesa Rusa (Kettlebell)', '/assets/exercises/0535-LHWF7us.webm', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente a los muslos.
Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.
Baja la pesa rusa hacia el suelo, dejando que se balancee entre las piernas.
Extiende rápidamente las caderas y las rodillas, usando el impulso para hacer que la pesa rusa suba hasta la altura del hombro.
Cuando la pesa rusa llegue a la altura del hombro, rota las muñecas y atrápala en posición de descanso, con el codo pegado al cuerpo y la pesa rusa apoyada en el antebrazo.
Baja la pesa rusa de vuelta a la posición inicial entre las piernas y repite el número de repeticiones deseado.'),
  ('0599', 'Sentado curl femoral en máquina', 'Piernas', 'Isquiotibiales', 'Máquina de Palanca', '/assets/exercises/0599-Zg3XY7P.webm', 'Ajusta la máquina a tu cuerpo y siéntate en ella con la espalda apoyada en el respaldo.
Coloca la parte baja de las piernas debajo de la palanca acolchada, justo por encima de los tobillos.
Sujeta las asas a los lados de la máquina para mayor apoyo.
Manteniendo la parte superior de las piernas inmóvil, exhala y flexiona las piernas hacia arriba todo lo que puedas.
Mantén la posición contraída durante una pausa breve mientras aprietas los isquiotibiales.
Inhala y baja lentamente la palanca de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0339', 'Tumbado femoral con mancuernas', 'Piernas', 'Isquiotibiales', 'Mancuernas', '/assets/exercises/0339-FkBIE6a.webm', 'Túmbate boca arriba con las piernas extendidas y una mancuerna apoyada sobre el abdomen bajo.
Flexiona las rodillas y lleva la mancuerna hacia los glúteos, manteniendo los pies apoyados en el suelo.
Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1604', 'El mejor estiramiento del mundo', 'Piernas', 'Isquiotibiales', 'Peso Corporal', '/assets/exercises/1604-DFGXwZr.webm', 'Comienza en posición de zancada con el pie derecho adelante y el pie izquierdo atrás.
Coloca las manos en el suelo a ambos lados de tu pie derecho.
Baja la rodilla izquierda hacia el suelo y extiende la pierna derecha, manteniendo el pie derecho plano sobre el suelo.
Gira el torso hacia la derecha, extendiendo el brazo derecho hacia el techo.
Mantén esta posición durante unos segundos, luego vuelve a la posición inicial.
Cambia de lado y repite el estiramiento con el pie izquierdo adelante.'),
  ('0582', 'Kneeling curl femoral en máquina', 'Piernas', 'Isquiotibiales', 'Máquina de Palanca', '/assets/exercises/0582-nnmCTLN.webm', 'Ajusta la máquina a tu cuerpo y selecciona el peso deseado.
Arrodíllate en la máquina mirando hacia abajo, con las rodillas apoyadas en la almohadilla y los pies asegurados bajo las almohadillas para los pies.
Sujeta las asas o los lados de la máquina para mayor estabilidad.
Manteniendo quieta la parte superior del cuerpo, exhala y flexiona las piernas hacia los glúteos doblando las rodillas.
Haz una pausa breve en la parte más alta del movimiento, contrayendo los isquiotibiales.
Inhala y baja lentamente las piernas de vuelta a la posición inicial, extendiendo por completo las rodillas.
Repite el número de repeticiones deseado.'),
  ('3021', 'Scapula flexiones', 'Pecho', 'Serrato Mayor', 'Peso Corporal', '/assets/exercises/3021-jV65tKx.webm', 'Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.
Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.
A medida que bajas, junta las escápulas y empuja el pecho hacia delante.
Haz una pausa por un momento en la posición baja, luego empuja de nuevo hacia arriba hasta la posición inicial.
Repite el número de repeticiones deseado.'),
  ('3011', 'Inclinado scapula flexiones', 'Pecho', 'Serrato Mayor', 'Peso Corporal', '/assets/exercises/3011-GdMa1ET.webm', 'Coloca un banco inclinado a un ángulo de 45 grados.
Coloca las manos en el banco, ligeramente más separadas que la altura de los hombros.
Coloca los pies en el suelo, separados a la altura de las caderas.
Baja el pecho hacia el banco, manteniendo los codos pegados al cuerpo.
Mientras bajas, retrae los omóplatos, apretándolos entre sí.
Empuja con las palmas para extender los brazos y regresar a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0759', 'Inclinado shoulder raises en multipower (Smith)', 'Pecho', 'Serrato Mayor', 'Multipower (Smith)', '/assets/exercises/0759-ayAHcEm.webm', 'Ajusta la máquina Smith a una posición inclinada.
Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.
Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.
Mantén la espalda recta y el core activado.
Eleva la barra hacia el techo, guiando el movimiento con los codos.
Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0050', 'Inclinado shoulder raise con barra', 'Pecho', 'Serrato Mayor', 'Barra', '/assets/exercises/0050-xi0yckC.webm', 'Coloca un banco inclinado a un ángulo de 45 grados.
Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.
Sujeta una barra con un agarre pronado, un poco más ancho que la separación de los hombros.
Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados.
Levanta lentamente la barra por encima de la cabeza, extendiendo completamente los brazos.
Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la altura de los hombros.
Repite el número de repeticiones deseado.'),
  ('0328', 'Inclinado shoulder raise con mancuernas', 'Pecho', 'Serrato Mayor', 'Mancuernas', '/assets/exercises/0328-6e2DcYX.webm', 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia abajo.
Apoya las mancuernas sobre los muslos y recuéstate en el banco.
Usa los muslos para ayudar a levantar las mancuernas hasta la altura de los hombros, luego gira las muñecas de modo que las palmas queden mirando hacia adelante.
Exhala y levanta lentamente las mancuernas por encima de la cabeza, manteniendo una ligera flexión en los codos.
Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la altura de los hombros.
Repite el número de repeticiones deseado.'),
  ('1494', 'Postura de mariposa (Yoga)', 'Piernas', 'Aductores', 'Peso Corporal', '/assets/exercises/1494-bWlZvXh.webm', 'Siéntate en el suelo con las piernas extendidas frente a ti.
Flexiona las rodillas y junta las plantas de los pies, dejando que las rodillas caigan hacia los lados.
Sujétate los tobillos o los pies con las manos.
Siéntate erguido y alarga la columna.
Presiona suavemente las rodillas hacia el suelo, sintiendo un estiramiento en la parte interna de los muslos.
Mantén esta posición durante unas cuantas respiraciones.
Para liberar, lleva lentamente las rodillas hacia arriba de nuevo y extiende las piernas.'),
  ('0168', 'Aducción de cadera en polea', 'Piernas', 'Aductores', 'Polea', '/assets/exercises/0168-hBGWILP.webm', 'Sujeta el manguito de tobillo a tu tobillo y ponte de pie frente a la máquina de cable.
Colócate lo suficientemente alejado de la máquina para que haya tensión en el cable.
Coloca las manos sobre la máquina para apoyarte.
Manteniendo la pierna recta, mueve lentamente la pierna por delante del cuerpo hacia la línea media.
Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1775', 'Side plank aducción de cadera', 'Piernas', 'Aductores', 'Peso Corporal', '/assets/exercises/1775-VO2qeJg.webm', 'Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.
Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro.
Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.
Manteniendo la posición de plancha lateral, levanta la pierna de arriba hacia el techo, manteniéndola recta.
Baja lentamente la pierna de nuevo a la posición inicial.
Repite el número de repeticiones deseado, luego cambia de lado.'),
  ('0598', 'Sentado aducción de cadera en máquina', 'Piernas', 'Aductores', 'Máquina de Palanca', '/assets/exercises/0598-oHsrypV.webm', 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo.
Coloca los pies sobre los apoyapiés y agarra las asas para mayor estabilidad.
Activa los aductores y junta lentamente las piernas, apretando la parte interna de los muslos.
Haz una pausa breve en el punto máximo de contracción, luego vuelve lentamente a la posición inicial.
Repite el número de repeticiones deseado.'),
  ('0710', 'Side abducción de cadera', 'Piernas', 'Abductores', 'Peso Corporal', '/assets/exercises/0710-7WaDzyL.webm', 'Ponte de pie con los pies separados a la altura de los hombros y las manos en las caderas.
Traslada el peso a una pierna y levanta la pierna opuesta hacia el lado, manteniéndola recta.
Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial.
Repite del otro lado.
Continúa alternando lados durante el número de repeticiones deseado.'),
  ('1774', 'Side bridge abducción de cadera', 'Piernas', 'Abductores', 'Peso Corporal', '/assets/exercises/1774-WL4EmxJ.webm', 'Túmbate de lado con las piernas extendidas y una sobre la otra.
Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro.
Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.
Manteniendo el core activado, levanta la pierna superior lo más alto posible sin rotar las caderas.
Haz una pausa por un momento en la posición alta, luego baja la pierna de nuevo.
Repite el número de repeticiones deseado, luego cambia de lado.'),
  ('0597', 'Sentado abducción de cadera en máquina', 'Piernas', 'Abductores', 'Máquina de Palanca', '/assets/exercises/0597-CHpahtl.webm', 'Ajusta la altura del asiento de modo que tus rodillas formen un ángulo de 90 grados.
Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre los apoyapiés.
Coloca las manos en las asas laterales para mayor estabilidad.
Activa los abductores y empuja lentamente las piernas hacia afuera, alejándolas de la línea media del cuerpo.
Haz una pausa al final del movimiento y luego junta lentamente las piernas de nuevo hasta la posición inicial.
Repite el número de repeticiones deseado.'),
  ('1427', 'Abducción de cadera con pierna recta', 'Piernas', 'Abductores', 'Peso Corporal', '/assets/exercises/1427-mQ1tBXn.webm', 'Túmbate de lado con las piernas rectas y apiladas una sobre la otra.
Coloca el brazo de abajo bajo la cabeza para apoyarte.
Activa el core y levanta la pierna superior lo más alto posible sin rotar las caderas ni inclinarte hacia atrás.
Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial.
Repite el número de repeticiones deseado, luego cambia de lado.'),
  ('1403', 'Neck side estiramiento', 'Cuello', 'Elevador de la Escápula', 'Peso Corporal', '/assets/exercises/1403-x2chWLO.webm', 'Ponte de pie o siéntate erguido con los hombros relajados.
Inclina la cabeza hacia un lado, llevando la oreja hacia el hombro.
Mantén el estiramiento durante 15-30 segundos.
Repite del otro lado.
Realiza de 2 a 4 series por cada lado.'),
  ('0716', 'Side push neck estiramiento', 'Cuello', 'Elevador de la Escápula', 'Peso Corporal', '/assets/exercises/0716-oQRJYkC.webm', 'Ponte de pie o siéntate erguido con los hombros relajados.
Inclina la cabeza hacia la derecha, llevando la oreja derecha hacia el hombro derecho.
Coloca la mano derecha en el lado izquierdo de la cabeza y aplica una presión suave para aumentar el estiramiento.
Mantén el estiramiento durante 15-30 segundos.
Repite hacia el otro lado, inclinando la cabeza hacia la izquierda y aplicando presión con la mano izquierda.
Repite el estiramiento 2-3 veces en cada lado.')
ON CONFLICT (id) DO NOTHING;
