  ('Muffins de avena y arándanos', 'Muffins sin azúcar con avena, huevo, banana y arándanos.', 220, 7, 40, 5, 'desayuno', 'avena,arandanos,horneado', 25, 'media', 2, 'omnivoro,vegetariano'),
  ('Pollo con arroz y vegetales', '200g de pechuga de pollo a la plancha con arroz integral y brócoli al vapor.', 620, 48, 65, 14, 'almuerzo', 'pollo,arroz,clasico,proteico', 30, 'facil', 1, 'omnivoro'),
  ('Milanesa de pollo con puré', 'Pechuga apanada al horno con puré de papas casero.', 720, 52, 58, 22, 'almuerzo', 'pollo,pure,milanesa,tradicional', 35, 'media', 1, 'omnivoro'),
  ('Lomo saltado', 'Lomo en tiras salteado con cebolla, tomate y papas fritas. Receta peruana.', 580, 45, 40, 20, 'almuerzo', 'carne,peru,papas,salteado', 25, 'media', 1, 'omnivoro'),
  ('Pasta con salsa boloñesa', 'Pasta integral con salsa de carne molida, tomate y queso rallado.', 680, 40, 72, 22, 'almuerzo', 'pasta,carne-molida,italiano,carbohidrato', 40, 'media', 1, 'omnivoro'),
  ('Arroz con lentejas (Mujadara)', 'Arroz y lentejas cocidos juntos con cebolla caramelizada. Plato árabe clásico.', 520, 22, 80, 12, 'almuerzo', 'lentejas,arroz,vegano,proteina-vegetal', 35, 'facil', 2, 'omnivoro,vegetariano,vegano,sin_gluten'),
  ('Salmón con quinoa y espárragos', 'Filet de salmón al horno con quinoa y espárragos grillados.', 590, 52, 38, 24, 'almuerzo', 'salmon,quinoa,omega-3,proteico', 25, 'media', 1, 'omnivoro,sin_gluten'),
  ('Ensalada César con pollo', 'Lechuga romana, pollo grillado, crutones, parmesano y aderezo César.', 450, 38, 18, 25, 'almuerzo', 'pollo,ensalada,bajo-carbohidrato,liviano', 15, 'facil', 1, 'omnivoro'),
  ('Locro argentino', 'Guiso de maíz, porotos, chorizo, panceta y carne. El clásico nacional.', 750, 42, 68, 30, 'almuerzo', 'tradicional,argentina,contundente,invierno', 120, 'dificil', 4, 'omnivoro'),
  ('Cazuela de pollo con verduras', 'Pollo en trozos con zanahorias, papas, cebolla y caldo de pollo.', 520, 44, 32, 18, 'almuerzo', 'pollo,verduras,guiso,saludable', 45, 'media', 2, 'omnivoro,sin_gluten'),
  ('Tarta de espinaca y queso', 'Tarta de masa casera rellena de espinaca, cebolla y queso.', 480, 24, 42, 24, 'almuerzo', 'espinaca,queso,tarta,vegetariano', 50, 'media', 4, 'omnivoro,vegetariano'),
  ('Albóndigas en salsa de tomate', 'Albóndigas de carne molida en salsa de tomate casera con pasta.', 620, 42, 45, 28, 'almuerzo', 'carne-molida,tomate,clasico,familiar', 45, 'media', 2, 'omnivoro'),
  ('Fideos con atún y tomate', 'Fideos integrales con atún al natural, tomate perita y olivas.', 560, 38, 68, 12, 'almuerzo', 'atun,pasta,rapido,economico', 20, 'facil', 1, 'omnivoro'),
  ('Hamburguesa casera con batata', 'Hamburguesa de carne casera en pan integral con batata al horno.', 680, 46, 52, 28, 'almuerzo', 'carne,hamburguesa,batata,proteico', 30, 'media', 1, 'omnivoro'),
  ('Wok de pollo con vegetales', 'Pollo y vegetales salteados en wok con salsa de soja y jengibre.', 480, 42, 32, 16, 'almuerzo', 'pollo,oriental,rapido,bajo-carbohidrato', 20, 'facil', 1, 'omnivoro,sin_gluten'),
  ('Empanadas de carne al horno', 'Empanadas de carne cortada a cuchillo con cebolla, huevo y aceitunas.', 480, 28, 52, 18, 'almuerzo', 'argentina,empanada,tradicional', 60, 'dificil', 4, 'omnivoro'),
  ('Pollo al curry con arroz basmati', 'Pechuga de pollo en salsa de curry con leche de coco y arroz basmati.', 620, 46, 58, 18, 'almuerzo', 'pollo,curry,indio,especiado', 35, 'media', 2, 'omnivoro,sin_gluten'),
  ('Ensalada de garbanzos', 'Garbanzos cocidos con tomate, pepino, cebolla morada y limón.', 380, 18, 52, 12, 'almuerzo', 'garbanzo,vegano,proteina-vegetal,rapido', 10, 'facil', 1, 'omnivoro,vegetariano,vegano,sin_gluten'),
